<?php
if (!defined('PHP_MUSIC_FRONT_CONTROLLER')) {
  http_response_code(404);
  exit;
}
// Portable NAS/media configuration - Rebuilt and Extended by Tea & Toast Software.
// config/bootstrap.php is loaded by the front controller.
// Emergency session clearance hook (Runs even if database is offline or missing)
if (isset($_GET['action']) && $_GET['action'] === 'clear_session_emergency') {
  if (session_status() === PHP_SESSION_NONE) {
    session_start();
  }
  session_destroy();
  php_music_set_admin_cookie('admin_session_token', '', time() - 3600);
  php_music_set_admin_cookie('admin_email', '', time() - 3600);
  header('Location: ./');
  exit;
}

// Detect HTTPS vs HTTP connection state early for session cookie security
$is_secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||
             ($_SERVER['SERVER_PORT'] == 443) ||
             (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) == 'https') ||
             (!empty($_SERVER['HTTP_X_FORWARDED_SSL']) && strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) == 'on');

function php_music_set_admin_cookie($name, $value, $expires)
{
  $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||
            (isset($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443) ||
            (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) === 'https') ||
            (!empty($_SERVER['HTTP_X_FORWARDED_SSL']) && strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) === 'on');
  setcookie($name, $value, [
    'expires' => $expires,
    'path' => '/',
    'secure' => $secure,
    'httponly' => true,
    'samesite' => 'Lax',
  ]);
}

function php_music_require_super_admin_actor($db)
{
  $actorId = (int)($_SESSION['admin_id'] ?? $_SESSION['user_id'] ?? 0);
  $statement = $db->prepare("SELECT status FROM users WHERE id = ?");
  $statement->execute([$actorId]);
  if ($statement->fetchColumn() !== 'super_admin') {
    http_response_code(403);
    die('Only the Super Administrator can change administrator access.');
  }
}

// Bypass Gzip compression for heavy files, streaming, and uploads to prevent memory exhaustion and play crashes
$raw_uri_gzip = $_SERVER['REQUEST_URI'] ?? '';
// FIXED: Added all scanning endpoints to bypass GZIP to prevent blank white screens from corrupted buffers
$is_gzip_bypass = preg_match('/action=(stream|thumb|get_stream|download_song|upload|batch|full_scan|force_rescan|rescan_covers|rescan_charts|vacuum_database|reset_rhythm_charts)/i', $raw_uri_gzip) || isset($_GET['download']) || isset($_GET['batch']);

if (!$is_gzip_bypass && !ini_get('zlib.output_compression') && isset($_SERVER['HTTP_ACCEPT_ENCODING']) && substr_count($_SERVER['HTTP_ACCEPT_ENCODING'], 'gzip')) {
  @ob_start('ob_gzhandler');
}
// Main site visually ignores warnings/notices to prevent JSON corruption, logs internally
error_reporting(E_ALL & ~E_NOTICE & ~E_WARNING & ~E_DEPRECATED);
ini_set('display_errors', '0');

// Do not generate .htaccess at runtime. Shared hosts and NAS packages expose
// different AllowOverride capabilities; an unsupported directive makes Apache
// reject every request in this directory before PHP can repair the file.
// DATA_ROOT is kept outside the web root by the installer, while direct PHP
// module access is denied by front-controller guards.

// AUTOMATIC ROBOTS.TXT: Prevent search engines and legitimate crawlers from indexing media and APIs
$robots_path = __DIR__ . '/robots.txt';
if (!file_exists($robots_path)) {
  $robots_content = <<<ROBOTS
User-agent: *
Disallow: /uploads/
Disallow: /getid3/
Disallow: /*?action=
Disallow: /*?share_type=
Disallow: /*?pwa=
Disallow: /*.db$
Disallow: /*.sqlite$

# Block AI Scrapers specifically
User-agent: GPTBot
Disallow: /
User-agent: ChatGPT-User
Disallow: /
User-agent: CCBot
Disallow: /
User-agent: anthropic-ai
Disallow: /
User-agent: Claude-Web
Disallow: /
ROBOTS;
  @file_put_contents($robots_path, $robots_content);
}

// GLOBAL CORS ENABLER: Execute BEFORE Firewall to allow Preflight OPTIONS to pass cross-origin!
$http_origin = $_SERVER['HTTP_ORIGIN'] ?? $_SERVER['HTTP_X_ORIGIN'] ?? '';
$raw_uri_cors = $_SERVER['REQUEST_URI'] ?? '';
$is_api_cors = strpos($raw_uri_cors, 'access=api') !== false || (isset($_GET['access']) && $_GET['access'] === 'api');

if ($is_api_cors) {
  // 1. Pure Public CORS for External API Player (No credentials needed)
  header("Access-Control-Allow-Origin: *");
} else {
  // 2. Standard CORS for Internal Web App (Requires credentials for sessions)
  if ($http_origin === 'null') {
    $http_origin = '*'; // Force wildcard for local testing
  } elseif (!$http_origin && isset($_SERVER['HTTP_REFERER'])) {
    $parsed_url = parse_url($_SERVER['HTTP_REFERER']);
    if (isset($parsed_url['host'])) {
      $http_origin = ($parsed_url['scheme'] ?? 'https') . '://' . $parsed_url['host'];
      if (isset($parsed_url['port'])) $http_origin .= ':' . $parsed_url['port'];
    }
  }

  if ($http_origin) {
    header("Access-Control-Allow-Origin: $http_origin");
    if ($http_origin !== '*') {
      header("Access-Control-Allow-Credentials: true");
    }
  } else {
    header("Access-Control-Allow-Origin: *");
  }
}

header("Access-Control-Expose-Headers: Content-Length, Content-Range, Accept-Ranges, Content-Type, Content-Disposition");
header("Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS");

if (isset($_SERVER['HTTP_ACCESS_CONTROL_REQUEST_HEADERS'])) {
  header("Access-Control-Allow-Headers: {$_SERVER['HTTP_ACCESS_CONTROL_REQUEST_HEADERS']}");
} else {
  header("Access-Control-Allow-Headers: Content-Type, Authorization, X-Requested-With, Range, Accept-Ranges, Cache-Control");
}

// INTERCEPT PREFLIGHT: Exit 200 OK immediately so browsers validate CORS securely
if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {
  header("Access-Control-Max-Age: 86400"); 
  header("Content-Length: 0");             
  header("Content-Type: text/plain");      
  exit(0);
}

// ANTI-SCRAPING FIREWALL: Now runs safely AFTER CORS validation
$raw_uri = $_SERVER['REQUEST_URI'] ?? '';
$temp_action = $_GET['action'] ?? '';

// Support JSON bodies sent by cross-origin fetch requests
$json_body = json_decode(file_get_contents('php://input'), true);
if (is_array($json_body)) {
  if (empty($temp_action) && isset($json_body['action'])) {
    $_GET['action'] = $json_body['action'];
    $temp_action = $_GET['action'];
  }
  if (isset($json_body['access'])) {
    $_GET['access'] = $json_body['access'];
  }
}

// Pre-extract action if the URL is mangled by play.html
if (empty($temp_action) && preg_match('/action=([a-zA-Z0-9_]+)/', $raw_uri, $act_match)) {
  $temp_action = $act_match[1];
}

$is_media_request = in_array($temp_action, ['embed', 'get_stream', 'get_image', 'download_song', 'download_cover']);
$is_explicit_api = strpos($raw_uri, 'access=api') !== false || (isset($_GET['access']) && $_GET['access'] === 'api');

$user_agent = $_SERVER['HTTP_USER_AGENT'] ?? '';
$bot_patterns = '/(python|curl|wget|bot|spider|crawl|scraper|scrapy|phantom|headless|selenium|puppet|puppeteer|httpclient|postman|insomnia|slurp|facebookexternalhit)/i';

// Exempt access=api calls from the strict bot User-Agent check
if (!$is_media_request && !$is_explicit_api && (empty($user_agent) || preg_match($bot_patterns, $user_agent))) {
  http_response_code(403);
  die("Access Denied: Automated scraping and bot activity are strictly prohibited.");
}

// MASS USE OPTIMIZATION: Force script into OPcache memory for max execution speed
if (function_exists('opcache_is_script_cached') && function_exists('opcache_compile_file')) {
  if (!@opcache_is_script_cached(__FILE__)) {
    @opcache_compile_file(__FILE__);
  }
}

if (isset($_GET['pwa'])) {
  if ($_GET['pwa'] == 'manifest') {
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    echo json_encode([
      "name" => "PHP Music",
      "short_name" => "Music",
      "start_url" => "./",
      "scope" => "./",
      "display" => "standalone",
      "background_color" => "#0a0a0a",
      "theme_color" => "#0a0a0a",
      "description" => "A simple, fast music player with user accounts and uploads.",
      "icons" => [[
          "src" => "?action=get_app_icon&size=192",
          "sizes" => "192x192",
          "type" => "image/svg+xml",
          "purpose" => "any maskable"
        ],[
          "src" => "?action=get_app_icon&size=512",
          "sizes" => "512x512",
          "type" => "image/svg+xml",
          "purpose" => "any maskable"
        ]
      ]
    ]);
    exit;
  }
  if ($_GET['pwa'] == 'sw') {
    header('Content-Type: application/javascript; charset=utf-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    echo <<<SW
const CACHE_NAME = 'php-music-cache-v30';
const STATIC_ASSETS =[
  './',
  'https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css',
  'https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css',
  'https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js',
  'https://cdn.jsdelivr.net/npm/sortablejs@latest/Sortable.min.js',
  'https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap',
  'https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/fonts/bootstrap-icons.woff2?v=1.11.3'
];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(STATIC_ASSETS)));
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1 && cacheName !== 'php-music-offline' && cacheName !== 'php-music-api-cache') {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  const isStream = url.searchParams.get('action') === 'get_stream';
  
  if (isStream) {
    event.respondWith(
      caches.match(event.request.url).then(async cachedResponse => {
        if (cachedResponse) {
          const rangeHeader = event.request.headers.get('range');
          if (!rangeHeader) return cachedResponse;
          
          const buffer = await cachedResponse.clone().arrayBuffer();
          const bytes = rangeHeader.match(/bytes=(\d+)-(\d+)?/);
          const start = Number(bytes[1]);
          const end = bytes[2] ? Number(bytes[2]) : buffer.byteLength - 1;
          
          const chunk = buffer.slice(start, end + 1);
          return new Response(chunk, {
            status: 206,
            statusText: 'Partial Content',
            headers: {
              'Content-Range': `bytes \${start}-\${end}/\${buffer.byteLength}`,
              'Content-Length': chunk.byteLength,
              'Content-Type': cachedResponse.headers.get('Content-Type') || 'audio/mpeg',
              'Accept-Ranges': 'bytes'
            }
          });
        }
        return fetch(event.request);
      })
    );
    return;
  }

  const isApiCall = url.searchParams.has('action') || url.searchParams.has('share_type');
  if (isApiCall) {
    event.respondWith(
      fetch(event.request).then(response => {
        if (event.request.method === 'GET' && response.ok) {
          const clone = response.clone();
          caches.open('php-music-api-cache').then(cache => cache.put(event.request, clone));
        }
        return response;
      }).catch(() => {
        if (event.request.method === 'GET') {
          return caches.match(event.request, { ignoreSearch: false, ignoreVary: true });
        }
        return new Response('{"status":"error", "message":"Network error"}', {
          status: 503,
          headers: { 'Content-Type': 'application/json' }
        });
      })
    );
    return;
  }

  const isPwaCall = url.searchParams.has('pwa');
  if (isPwaCall || event.request.headers.get('range')) {
    event.respondWith(fetch(event.request));
    return;
  }
  
  if (event.request.mode === 'navigate' || url.pathname.endsWith('/')) {
    event.respondWith(
      fetch(event.request).then(networkResponse => {
        return caches.open(CACHE_NAME).then(cache => {
          cache.put(event.request, networkResponse.clone());
          return networkResponse;
        });
      }).catch(() => {
        return caches.match(event.request);
      })
    );
    return;
  }
  
  event.respondWith(
    caches.match(event.request).then(response => {
      return response || fetch(event.request).then(networkResponse => {
        if (networkResponse && networkResponse.ok) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, responseToCache));
        }
        return networkResponse;
      });
    })
  );
});

self.addEventListener('notificationclick', event => {
  event.notification.close();
  const chatId = event.notification.data ? event.notification.data.chatId : null;
  const chatType = event.notification.data ? event.notification.data.chatType : 'user';
  const chatName = event.notification.data ? event.notification.data.chatName : 'User';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(windowClients => {
      for (let client of windowClients) {
        if ('focus' in client) {
          client.focus();
          if (chatId) {
            client.postMessage({ action: 'open_chat', chatId: chatId, chatType: chatType, chatName: chatName });
          }
          return;
        }
      }
      if (clients.openWindow) {
        const url = new URL('./', self.location.origin);
        if (chatId) {
          url.searchParams.set('open_chat_id', chatId);
          url.searchParams.set('open_chat_type', chatType);
          url.searchParams.set('open_chat_name', chatName);
        }
        return clients.openWindow(url.href);
      }
    })
  );
});
SW;
    exit;
  }
}

