                          <?php if ($dbm_search): ?><a href="<?= dbm_e(dbm_self_url(['db' => $dbName, 'table' => $curTable, 'limit' => $dbm_limit])) ?>" class="dbm-btn dbm-btn-sm dbm-btn-outline">Clear</a><?php endif; ?>
