                  const res = await driveFetch('upload_url', { action: 'upload_url', url: url }, targetPath);
                  
                  finishIdeSimulatedProgress();
                  submitBtn.disabled = false;
                  submitBtn.innerText = 'Download';
                  
                  if (res.success) {
                    termLog(`Downloaded URL successfully.`);
                    loadTree(targetPath);
                    bootstrap.Modal.getInstance(document.getElementById('ide-upload-url-modal')).hide();
                  } else {
                    termLog(`Download failed: ${res.error}`, true);
                    alert(res.error);
                  }
                }
              };

              document.getElementById('ide-upload-url-submit').onclick = handleIdeUploadUrlSubmit;
              document.getElementById('ide-upload-url-input').addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleIdeUploadUrlSubmit();
                }
              });

              const driveFetch = async (action, body, reqPath = '') => {
                try {
                  body.csrf_token = '<?php echo $_SESSION['admin_csrf_token'] ?? ''; ?>';
                  const res = await fetch(`?access=admin&page=drive&api=true&action=${action}&path=${encodeURIComponent(reqPath)}`, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json', 'X-CSRF-TOKEN': body.csrf_token},
                    body: JSON.stringify(body)
                  });
                  if (!res.ok) throw new Error(`HTTP Error ${res.status}`);
                  return await res.json();
                } catch (e) {
                  termLog(`API Error (${action}): ${e.message}`, true);
                  return { success: false, error: e.message };
                }
              };
  
              window.ideChunkedUpload = async (filesList, pathsList, targetPath = '') => {
                if (filesList.length === 0) return;
                termLog(`Starting chunked upload for ${filesList.length} file(s)...`);
                const csrfToken = '<?php echo $_SESSION['admin_csrf_token'] ?? ''; ?>';
                let totalUploaded = 0;
                let totalSize = Array.from(filesList).reduce((sum, f) => sum + f.size, 0);
                let loadedSize = 0;
                updateIdeProgress(0, true);
  
                for (let i = 0; i < filesList.length; i++) {
                  const file = filesList[i];
                  const chunkSize = 5 * 1024 * 1024;
                  const totalChunks = Math.ceil(file.size / chunkSize) || 1;
                  const fileId = 'ide_up_' + Math.random().toString(36).substring(2, 9);
                  const rawRelPath = pathsList[i] || file.name;
                  const fullPath = targetPath ? (targetPath + '/' + rawRelPath) : rawRelPath;
  
                  let success = true;
                  for (let chunkIndex = 0; chunkIndex < totalChunks; chunkIndex++) {
                    const start = chunkIndex * chunkSize;
                    const end = Math.min(start + chunkSize, file.size);
                    const chunkBlob = file.slice(start, end);
  
                    const fd = new FormData();
                    fd.append('action', 'upload');
                    fd.append('csrf_token', csrfToken);
                    fd.append('files[]', chunkBlob, file.name);
                    fd.append('paths[]', fullPath);
                    fd.append('chunk', chunkIndex);
                    fd.append('chunks', totalChunks);
                    fd.append('file_id', fileId);
  
                    try {
                      const res = await fetch(`?access=admin&page=drive&api=true`, { method: 'POST', body: fd }).then(r => r.json());
                      if (!res.success && res.error && res.error.startsWith('CONFLICT|')) {
                        fd.append('override', '1');
                        const resRetry = await fetch(`?access=admin&page=drive&api=true`, { method: 'POST', body: fd }).then(r => r.json());
                        if (!resRetry.success) throw new Error(resRetry.error);
                      } else if (!res.success) {
                        throw new Error(res.error);
                      }
                      loadedSize += chunkBlob.size;
                      const overallProgress = Math.min(100, Math.round((loadedSize / totalSize) * 100));
                      updateIdeProgress(overallProgress, true);
                      
                      const progress = Math.round(((chunkIndex + 1) / totalChunks) * 100);
                      if (totalChunks > 1 && (progress % 25 === 0 || progress === 100)) {
                        termLog(`[${file.name}] Uploading... ${progress}%`);
                      }
                    } catch (err) {
                      termLog(`[${file.name}] Upload failed: ${err.message}`, true);
                      success = false;
                      break;
                    }
                  }
                  if (success) {
                    if (totalChunks <= 1) termLog(`[${file.name}] Uploaded successfully.`);
                    else termLog(`[${file.name}] Stitching complete.`);
                    totalUploaded++;
                  }
                }
                if (totalUploaded > 0) {
                  loadTree(targetPath);
                }
                setTimeout(() => updateIdeProgress(0, false), 1000);
              };
  
              const handleUploadClick = (targetPath, isFolder = false) => {
                const fileInput = document.createElement('input');
                fileInput.type = 'file';
                fileInput.multiple = true;
                if (isFolder) {
                  fileInput.setAttribute('webkitdirectory', '');
                  fileInput.setAttribute('directory', '');
                }
                fileInput.onchange = async (e) => {
                  if (e.target.files.length > 0) {
                    const filesArr = Array.from(e.target.files);
                    let pathsArr = filesArr.map(f => f.webkitRelativePath || f.name);
                    
                    if (isFolder && pathsArr.length > 0 && pathsArr[0].includes('/')) {
                       const rootFolderName = pathsArr[0].split('/')[0];
                       const listRes = await fetch(`?access=admin&page=drive&api=true&action=list&path=${encodeURIComponent(targetPath)}`).then(r => r.json()).catch(() => null);
                       if (listRes && listRes.success && listRes.folders) {
                          const existingFolders = listRes.folders.map(f => f.name);
                          if (existingFolders.includes(rootFolderName)) {
                             let counter = 1;
                             let newRoot = `${rootFolderName}_(${counter})`;
                             while(existingFolders.includes(newRoot)) {
                                counter++;
                                newRoot = `${rootFolderName}_(${counter})`;
                             }
                             pathsArr = pathsArr.map(p => {
                                const parts = p.split('/');
                                parts[0] = newRoot;
                                return parts.join('/');
                             });
                             termLog(`Folder renamed to ${newRoot} to avoid collision.`);
                          }
                       }
                    }
                    await window.ideChunkedUpload(filesArr, pathsArr, targetPath);
                  }
                };
                fileInput.click();
              };
  
              const handleUploadUrlClick = async (targetPath) => {
                const modalEl = document.getElementById('ide-upload-url-modal');
                const inputEl = document.getElementById('ide-upload-url-input');
                document.getElementById('ide-upload-url-path').value = targetPath;
                inputEl.value = '';
                
                const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
                modal.show();
                setTimeout(() => inputEl.focus(), 150);
              };

              document.getElementById('ide-tree-new-file').onclick = () => {
