              document.getElementById('ide-btn-download').onclick = () => {
                const pathStr = document.getElementById('ide-ctx-path').value;
                const paths = pathStr.split('|');
                const isFolder = document.getElementById('ide-ctx-is-folder').value === '1';
  
                if (paths.length > 1) {
