      $db->prepare("DELETE FROM blocks WHERE blocker_id = ? OR blocked_id = ?")->execute([$user_id, $user_id]);
      $db->prepare("DELETE FROM rhythm_scores WHERE user_id = ?")->execute([$user_id]);
