    case 'upload_song':
      if (!$user_id) { http_response_code(403); exit; }

      $stmt = $db->prepare("SELECT verified, last_upload_date, daily_upload_count FROM users WHERE id = ?");
      $stmt->execute([$user_id]);
      $user_data = $stmt->fetch();

      if (!$user_data) {
        http_response_code(403);
        send_json(['status' => 'error', 'message' => 'User not found.']);
      }

      if ($user_data['verified'] !== 'yes') {
        http_response_code(403);
        send_json(['status' => 'error', 'message' => 'Your account is not verified for uploads.']);
      }

      $today = date('Y-m-d');
      $daily_upload_count = 0;
      if ($user_data['last_upload_date'] === $today) {
        $daily_upload_count = (int)$user_data['daily_upload_count'];
      }

      if ($daily_upload_count >= DAILY_UPLOAD_LIMIT) {
        http_response_code(429);
        send_json(['status' => 'error', 'message' => 'Daily upload limit of ' . DAILY_UPLOAD_LIMIT . ' songs reached.']);
      }

      if (!class_exists('getID3')) {
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'getID3 library is missing.']);
      }
      if (isset($_FILES['song'])) {
        $file = $_FILES['song'];
        if ($file['error'] !== UPLOAD_ERR_OK) {
          http_response_code(400);
          send_json(['status' => 'error', 'message' => 'Upload error: ' . $file['error']]);
        }
        
        $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        $allowed_exts = ['mp3', 'flac', 'm4a', 'ogg', 'wav'];
        if (!in_array($ext, $allowed_exts)) {
          http_response_code(400);
          send_json(['status' => 'error', 'message' => 'Security Error: Invalid file format. Only MP3, FLAC, M4A, OGG, and WAV are allowed.']);
        }
        
        $getID3 = new getID3;
        $getID3->setOption(['encoding' => 'UTF-8']);
        $info = $getID3->analyze($file['tmp_name']);
        getid3_lib::CopyTagsToComments($info);

        $uploader_name = $_SESSION['user_artist'] ?? 'Unknown Artist';
        $posted_collabs = trim($_POST['artist'] ?? '');
        $is_collaborative = intval($_POST['is_collaborative'] ?? 0);
        
        $artist = extract_safe_tag($info['comments'] ?? [], 'artist', $uploader_name);
        if (empty($artist) || $artist === 'Unknown Artist') $artist = $uploader_name;
        
        // Use precision tracking for the uploader
        if (stripos($artist, "(id:") === false) {
           $artist .= " (id:" . $user_id . ")";
        }
        
        $collab_user_ids = [];
        if ($is_collaborative === 1 && !empty($posted_collabs)) {
          $collab_inputs = array_map('trim', explode(',', $posted_collabs));
          foreach ($collab_inputs as $c_input) {
            if (empty($c_input)) continue;
            $stmt_c = $db->prepare("SELECT id, artist FROM users WHERE id = ? OR email = ? COLLATE NOCASE");
            $stmt_c->execute([$c_input, $c_input]);
            $c_user = $stmt_c->fetch();
            if ($c_user && $c_user['id'] != $user_id) {
              $collab_user_ids[] = $c_user['id'];
              // Require approval via link: Do not automatically append their name to the track
            }
          }
        }
        
        $main_artist = trim(preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $artist)[0] ?? '');
        $artist_path = sanitize_for_path($main_artist);
        // SHARDING: Split uploads into 256 physical subfolders to prevent Linux inode collapse
        $shard = substr(md5($artist_path), 0, 2);
        $upload_dir = MEDIA_UPLOAD_ROOT . '/' . $shard . '/' . $artist_path;
        if (!is_dir($upload_dir)) {
          mkdir($upload_dir, 0755, true);
        }

        $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        $filename = uniqid('m_') . '.' . $ext;
        $filePath = $upload_dir . '/' . $filename;
        if (move_uploaded_file($file['tmp_name'], $filePath)) {
          $title = extract_safe_tag($info['comments'] ?? [], 'title', pathinfo($file['name'], PATHINFO_FILENAME));
          $album = extract_safe_tag($info['comments'] ?? [], 'album', 'Unknown Album');
          $year = (int)($info['comments']['year'][0] ?? 0);
          $duration = (int)($info['playtime_seconds'] ?? 0);
          $bitrate = (int)($info['audio']['bitrate'] ?? 0);
          $genre = extract_safe_tag($info['comments'] ?? [], 'genre', (trim($_POST['genre'] ?? '') ?: 'Uploaded'));
          
          $replaygain = 0;
          if (!empty($info['tags']['id3v2']['TXXX'])) {
            foreach($info['tags']['id3v2']['TXXX'] as $txxx) {
              if (strtoupper($txxx['description'] ?? '') === 'REPLAYGAIN_TRACK_GAIN') {
                $replaygain = (float)str_replace(' dB', '', $txxx['data']);
              }
            }
          } elseif (!empty($info['comments']['replaygain_track_gain'][0])) {
            $replaygain = (float)str_replace(' dB', '', $info['comments']['replaygain_track_gain'][0]);
          }

          $raw_image_data = isset($info['comments']['picture'][0]['data']) ? $info['comments']['picture'][0]['data'] : null;
          $webp_image_data = process_image_to_webp($raw_image_data);

          $filePath = php_music_store_media_path($filePath); // Portable, MEDIA_ROOT-relative DB path
          if ($filePath === false) {
            @unlink($upload_dir . '/' . $filename);
            http_response_code(500);
            send_json(['status' => 'error', 'message' => 'Uploaded file failed media-root validation.']);
          }
          $actual_mtime = filemtime(php_music_resolve_media_path($filePath)); // Get exact OS file modification time
          $is_private = intval($_POST['is_private'] ?? 0);
          $is_collaborative = intval($_POST['is_collaborative'] ?? 0);
          
          $stmt = $db->prepare("INSERT INTO music (user_id, file, title, artist, album, genre, year, duration, bitrate, image, last_modified, is_private, is_collaborative, replaygain) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
          $stmt->execute([$user_id, $filePath, $title, $artist, $album, $genre, $year, $duration, $bitrate, $webp_image_data, $actual_mtime, $is_private, $is_collaborative, $replaygain]);
          $new_song_id = $db->lastInsertId();

          if ($is_private == 0) {
            $db->prepare("INSERT INTO activity_feed (user_id, action, target_name) VALUES (?, ?, ?)")->execute([$user_id, 'uploaded a new song', $title]);
          }
          
          if (!empty($collab_user_ids)) {
            $expires_at = date('Y-m-d H:i:s', time() + 3600); // Strict 1 hour duration
            $stmt_inv = $db->prepare("INSERT INTO song_invites (token, song_id, expires_at) VALUES (?, ?, ?)");
            $stmt_msg = $db->prepare("INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)");
            foreach ($collab_user_ids as $c_id) {
              $token = bin2hex(random_bytes(16));
              $stmt_inv->execute([$token, $new_song_id, $expires_at]);
              
              $invite_url = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ? "https" : "http") . "://" . $_SERVER['HTTP_HOST'] . strtok($_SERVER["REQUEST_URI"], '?') . "?song_invite=" . $token;
              $msg_content = "I have invited you to collaborate on my new track: [b]" . $title . "[/b].\n\nClick here to accept: [url]" . $invite_url . "[/url]\n\nThis invite expires in 1 hour.";
              $stmt_msg->execute([$user_id, $c_id, $msg_content]);
            }
          }

          try {
            $db->exec("CREATE TABLE IF NOT EXISTS rhythm_charts (
              song_id INTEGER NOT NULL, difficulty TEXT NOT NULL, notes_json TEXT, level INTEGER DEFAULT 1,
              PRIMARY KEY (song_id, difficulty), FOREIGN KEY (song_id) REFERENCES music(id) ON DELETE CASCADE
            );");
            $rgDiffs = ['easy', 'medium', 'hard', 'expert', 'master', 'demon'];
            $stmt_chart = $db->prepare("INSERT OR REPLACE INTO rhythm_charts (song_id, difficulty, notes_json, level) VALUES (?, ?, ?, ?)");
            foreach ($rgDiffs as $diff) {
              $c_notes = generatePhpChart($new_song_id, $duration, $diff, 1.0);
              $c_level = calculatePhpLevel($c_notes, $duration, $diff, 1.0);
              $stmt_chart->execute([$new_song_id, $diff, json_encode($c_notes), $c_level]);
            }
          } catch(Exception $e) {}

          $new_count = ($user_data['last_upload_date'] === $today) ? $daily_upload_count + 1 : 1;
          $update_stmt = $db->prepare("UPDATE users SET daily_upload_count = ?, last_upload_date = ? WHERE id = ?");
          $update_stmt->execute([$new_count, $today, $user_id]);

          send_json(['status' => 'success', 'message' => 'File uploaded.']);
        } else {
          http_response_code(500);
          send_json(['status' => 'error', 'message' => 'Failed to move uploaded file.']);
        }
      }
      break;

    case 'delete_song':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $song_id = intval($data['id']);

      $stmt = $db->prepare("SELECT file, user_id FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();
      
      if ($song && ($song['user_id'] == $user_id || $is_admin || $is_super_admin)) {
        $db->prepare("DELETE FROM music WHERE id = ?")->execute([$song_id]);
        $file_path = php_music_require_media_file($song['file']);
        if ($file_path !== false) {
          @unlink($file_path);
        }
        send_json(['status' => 'success', 'message' => 'Song deleted.']);
      } else {
        http_response_code(403);
        send_json(['status' => 'error', 'message' => 'You do not have permission.']);
      }
      break;

    case 'download_song':
      $song_id = intval($_GET['id'] ?? 0);
      $stmt = $db->prepare("SELECT file, title, artist, user_id, is_private FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();

      if ($song) {
        $may_download = (int)$song['is_private'] === 0 || (int)$song['user_id'] === (int)$user_id || $is_super_admin == 1;
        if (!$may_download && $user_id) {
          $stmt_art = $db->prepare("SELECT artist FROM users WHERE id = ?");
          $stmt_art->execute([$user_id]);
          $viewer_artist = $stmt_art->fetchColumn();
          $may_download = $viewer_artist && $db->query("SELECT match_artist(" . $db->quote($song['artist']) . ", " . $db->quote($viewer_artist) . ")")->fetchColumn() == 1;
        }
        if (!$may_download) {
          http_response_code(403);
          send_json(['status' => 'error', 'message' => 'This song is private.']);
        }
        $file_path = php_music_require_media_file($song['file']);

        if ($file_path !== false) {
          while (ob_get_level() > 0) { @ob_end_clean(); }
          $ext = pathinfo($file_path, PATHINFO_EXTENSION);
          $dl_name = trim(($song['title'] ?? '') . (($song['artist'] && $song['title']) ? ' - ' : '') . ($song['artist'] ?? ''));
          $dl_name = $dl_name ? $dl_name . '.' . $ext : basename($file_path);
          $encoded = rawurlencode($dl_name);
          $finfo = finfo_open(FILEINFO_MIME_TYPE);
          header('Content-Type: ' . finfo_file($finfo, $file_path));
          finfo_close($finfo);
          header('Content-Length: ' . filesize($file_path));
          header("Content-Disposition: attachment; filename=\"song." . $ext . "\"; filename*=UTF-8''" . $encoded);
          @flush();
          readfile($file_path);
          exit;
        }
      }
      http_response_code(404);
      send_json(['status' => 'error', 'message' => 'File not found.']);
      break;

    case 'inspect_audio':
      if (!$user_id) { http_response_code(403); exit; }
      if (!isset($_FILES['audio'])) send_json(['ok' => false, 'message' => 'No audio file']);
      $tmp = $_FILES['audio']['tmp_name'];
      $reader = new getID3();
      $reader->setOption(['encoding' => 'UTF-8']);
      $info = $reader->analyze($tmp);
      getid3_lib::CopyTagsToComments($info);
      $audio = $info['audio'] ?? [];
      $bitrate = isset($info['audio']['bitrate']) ? (int) round(((float) $info['audio']['bitrate']) / 1000) : null;
      $playtime = isset($info['playtime_seconds']) ? (float) $info['playtime_seconds'] : null;
      
      send_json([
        'ok' => true,
        'message' => 'Metadata read locally with getID3.',
        'metadata' => [
          'format' => $audio['dataformat'] ?? $info['fileformat'] ?? '—',
          'bitrate' => $bitrate ? $bitrate . ' kbps' : '—',
          'sampleRate' => isset($audio['sample_rate']) ? number_format((float) $audio['sample_rate']) . ' Hz' : '—',
          'channels' => $audio['channels'] ?? '—',
          'duration' => $playtime,
          'encoder' => $audio['encoder'] ?? '—',
          'title' => extract_safe_tag($info['comments'] ?? [], 'title', '—'),
          'artist' => extract_safe_tag($info['comments'] ?? [], 'artist', '—'),
          'album' => extract_safe_tag($info['comments'] ?? [], 'album', '—')
        ]
      ]);
      break;

    case 'save_audio_editor':
      if (!$user_id) { http_response_code(403); exit; }
      try {
        if (!isset($_FILES['audio'])) throw new Exception('No audio file.');
        $audioUpload = $_FILES['audio'];
        $title = trim(htmlspecialchars($_POST['title'] ?? '', ENT_QUOTES, 'UTF-8'));
        $artist = trim(htmlspecialchars($_POST['artist'] ?? '', ENT_QUOTES, 'UTF-8'));
        $album = trim(htmlspecialchars($_POST['album'] ?? '', ENT_QUOTES, 'UTF-8'));
        $existing_id = !empty($_POST['song_id']) ? (int)$_POST['song_id'] : null;
        
        $ext = strtolower(pathinfo($audioUpload['name'], PATHINFO_EXTENSION));
        if (!in_array($ext, ['mp3', 'flac', 'm4a', 'ogg', 'wav'])) throw new Exception('Invalid extension.');

        if ($existing_id) {
          $stmt = $db->prepare("SELECT file FROM music WHERE id = ? AND (user_id = ? OR ? = 1)");
          $stmt->execute([$existing_id, $user_id, $is_admin]);
          $existing_file = $stmt->fetchColumn();
          if (!$existing_file) throw new Exception('Unauthorized or song not found.');
          $audioPath = php_music_require_media_file($existing_file);
          if ($audioPath === false) throw new Exception('Stored media path failed validation.');
        } else {
          $shard = substr(md5($artist), 0, 2);
          $upload_dir = MEDIA_UPLOAD_ROOT . '/' . $shard . '/' . sanitize_for_path($artist);
          if (!is_dir($upload_dir)) mkdir($upload_dir, 0755, true);
          $filename = uniqid('ae_') . '.' . $ext;
          $audioPath = $upload_dir . '/' . $filename;
        }

        move_uploaded_file($audioUpload['tmp_name'], $audioPath);

        $cover = null;
        $webp_data = null;
        if (isset($_FILES['cover']) && $_FILES['cover']['error'] === UPLOAD_ERR_OK) {
          $raw = file_get_contents($_FILES['cover']['tmp_name']);
          $webp_data = process_image_to_webp($raw);
          $cover = [
            'data' => process_image_to_jpeg($raw),
            'mime' => 'image/jpeg'
          ];
        }

        if (file_exists(__DIR__ . '/getid3/write.php')) {
          require_once __DIR__ . '/getid3/write.php';
          $writer = new getid3_writetags();
          $writer->filename = $audioPath;
          $writer->tagformats = ['id3v1', 'id3v2.3'];
          if ($ext === 'flac') $writer->tagformats = ['metaflac'];
          if ($ext === 'ogg') $writer->tagformats = ['vorbiscomment'];
          $writer->overwrite_tags = true;
          $writer->tag_encoding = 'UTF-8';
          $writer->tag_data = [
            'title' => [$title],
            'artist' => [$artist],
            'album' => [$album]
          ];
          if ($cover && $ext === 'mp3') {
            $writer->tag_data['attached_picture'] = [[
              'data' => $cover['data'],
              'picturetypeid' => 3,
              'description' => 'Cover',
              'mime' => $cover['mime']
            ]];
          }
          $writer->WriteTags();
        }

        $reader = new getID3();
        $info = $reader->analyze($audioPath);
        $duration = (int)($info['playtime_seconds'] ?? 0);
        $bitrate = (int)($info['audio']['bitrate'] ?? 0);
        $mtime = filemtime($audioPath);

        if ($existing_id) {
          if ($webp_data) {
            $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, duration = ?, bitrate = ?, image = ?, last_modified = ? WHERE id = ?")->execute([$title, $artist, $album, $duration, $bitrate, $webp_data, $mtime, $existing_id]);
          } else {
            $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, duration = ?, bitrate = ?, last_modified = ? WHERE id = ?")->execute([$title, $artist, $album, $duration, $bitrate, $mtime, $existing_id]);
          }
        } else {
          $storedAudioPath = php_music_store_media_path($audioPath);
          if ($storedAudioPath === false) throw new Exception('Saved file failed media-root validation.');
          $stmt = $db->prepare("INSERT INTO music (user_id, file, title, artist, album, duration, bitrate, image, last_modified) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
          $stmt->execute([$user_id, $storedAudioPath, $title, $artist, $album, $duration, $bitrate, $webp_data, $mtime]);
        }

        send_json(['ok' => true, 'message' => 'Saved to library successfully.']);
      } catch(Exception $e) {
        send_json(['ok' => false, 'message' => $e->getMessage()]);
      }
      break;

    case 'get_song_versions':
      if (!$user_id) { http_response_code(403); exit; }
      $song_id = (int)json_decode(file_get_contents('php://input'), true)['id'];
      $stmt = $db->prepare("SELECT file, user_id FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();
      if ($song && ($song['user_id'] == $user_id || $is_admin == 1)) {
        $file = $song['file'];
        $verDir = DATA_ROOT . '/.file_version/' . basename($file);
        $versions = [];
        if (is_dir($verDir)) {
          foreach (array_diff(scandir($verDir), ['.', '..']) as $v) {
            $versions[] = ['name' => $v, 'mtime' => filemtime($verDir . '/' . $v), 'size' => round(filesize($verDir . '/' . $v)/1048576, 2).' MB'];
          }
          usort($versions, function($a, $b) { return $b['mtime'] - $a['mtime']; });
          // Hardware optimization: Return only latest 10 versions to prevent memory bloat
          $versions = array_slice($versions, 0, 10);
        }
        send_json(['status' => 'success', 'versions' => $versions]);
      } else {
        http_response_code(403); send_json(['status' => 'error', 'message' => 'Unauthorized']);
      }
      break;

    case 'restore_song_version':
      if (!$user_id) { http_response_code(403); exit; }
      $data = json_decode(file_get_contents('php://input'), true);
      $song_id = (int)$data['id'];
      $version_name = basename($data['version_name']);
      $stmt = $db->prepare("SELECT file, user_id FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();
      if ($song && ($song['user_id'] == $user_id || $is_admin == 1)) {
        $file = php_music_require_media_file($song['file']);
        if ($file === false) send_json(['status' => 'error', 'message' => 'Stored media path failed validation']);
        $src = DATA_ROOT . '/.file_version/' . basename($file) . '/' . $version_name;
        if (!file_exists($src)) {
          send_json(['status' => 'error', 'message' => 'Version not found']);
        }
        
        // Securely backup the current file state before rollback
        $verDir = DATA_ROOT . '/.file_version/' . basename($file);
        if (!is_dir($verDir)) @mkdir($verDir, 0755, true);
        @copy($file, $verDir . '/' . basename($file) . '_' . date('Y-m-d_H-i-s'));
        
        // Commit the rollback
        copy($src, $file);
        $db->prepare("UPDATE music SET last_modified = ? WHERE id = ?")->execute([time(), $song_id]);
        send_json(['status' => 'success', 'message' => 'Restored successfully']);
      } else {
        http_response_code(403); send_json(['status' => 'error', 'message' => 'Unauthorized']);
      }
      break;

    case 'edit_metadata':
      if (!$user_id) { http_response_code(403); exit; }
      $song_id = intval($_POST['id'] ?? 0);
      $new_title = trim(htmlspecialchars($_POST['title'] ?? '', ENT_QUOTES, 'UTF-8'));
      $new_artist = trim(htmlspecialchars($_POST['artist'] ?? '', ENT_QUOTES, 'UTF-8'));
      $new_album = trim(htmlspecialchars($_POST['album'] ?? '', ENT_QUOTES, 'UTF-8'));
      $new_genre = trim(htmlspecialchars($_POST['genre'] ?? '', ENT_QUOTES, 'UTF-8'));
      $new_lyrics = trim(htmlspecialchars($_POST['lyrics'] ?? '', ENT_QUOTES, 'UTF-8'));

      $stmt = $db->prepare("SELECT user_id, file FROM music WHERE id = ?");
      $stmt->execute([$song_id]);
      $song = $stmt->fetch();

      if ($song && ($song['user_id'] == $user_id || $is_admin || $is_super_admin)) {
        $file_path = php_music_require_media_file($song['file']);
        if ($file_path === false) {
          http_response_code(409);
          send_json(['status' => 'error', 'message' => 'Stored media path failed validation.']);
        }
        $song['file'] = $file_path; // Override with resolved path

        $is_private = intval($_POST['is_private'] ?? 0);
        $is_collaborative = intval($_POST['is_collaborative'] ?? 0);

        if ($is_collaborative === 1) {
          // Append base ID if missing
          if (stripos($new_artist, "(id:" . $song['user_id'] . ")") === false) {
            $new_artist .= " (id:" . $song['user_id'] . ")";
          }
          $stmt_collabs = $db->prepare("SELECT u.id, u.artist FROM song_collaborators sc JOIN users u ON sc.user_id = u.id WHERE sc.song_id = ?");
          $stmt_collabs->execute([$song_id]);
          $active_collabs = $stmt_collabs->fetchAll();
          foreach($active_collabs as $ac) {
            if (stripos($new_artist, "(id:" . $ac['id'] . ")") === false) {
              $new_artist .= ", " . $ac['artist'] . " (id:" . $ac['id'] . ")";
            }
          }
        }

        $update_fields = ["title = ?", "artist = ?", "album = ?", "genre = ?", "lyrics = ?", "is_private = ?", "is_collaborative = ?"];
        $update_params = [$new_title, $new_artist, $new_album, $new_genre, $new_lyrics, $is_private, $is_collaborative];

        if ($is_collaborative === 0) {
          $db->prepare("DELETE FROM song_collaborators WHERE song_id = ?")->execute([$song_id]);
          $db->prepare("DELETE FROM song_invites WHERE song_id = ?")->execute([$song_id]);
        }

        $jpeg_data = null;
        $webp_data = null;
        if (isset($_FILES['cover_image']) && $_FILES['cover_image']['error'] === UPLOAD_ERR_OK) {
          $raw_img = file_get_contents($_FILES['cover_image']['tmp_name']);
          $webp_data = process_image_to_webp($raw_img);
          $jpeg_data = process_image_to_jpeg($raw_img);
          if ($webp_data) {
            $update_fields[] = "image = ?";
            $update_params[] = $webp_data;
            
            // Save cover image to dedicated covers directories (covers/songs and covers/albums)
            $covers_songs_dir = DATA_ROOT . '/covers/songs';
            $covers_albums_dir = DATA_ROOT . '/covers/albums';
            if (!is_dir($covers_songs_dir)) @mkdir($covers_songs_dir, 0755, true);
            if (!is_dir($covers_albums_dir)) @mkdir($covers_albums_dir, 0755, true);

            if ($jpeg_data) {
              // 1. Save cover to covers/songs folder
              $song_cover_path = $covers_songs_dir . '/' . $song_id . '.jpg';
              @file_put_contents($song_cover_path, $jpeg_data);

              // 2. Save cover to covers/albums folder if an album name is specified
              if (!empty($new_album) && strtolower($new_album) !== 'unknown album') {
                $album_slug = sanitize_for_path($new_album);
                if ($album_slug !== '') {
                  $album_cover_path = $covers_albums_dir . '/' . $album_slug . '.jpg';
                  @file_put_contents($album_cover_path, $jpeg_data);
                }
              }
            }
          }
        }

        $update_params[] = $song_id;
        $stmt = $db->prepare("UPDATE music SET " . implode(", ", $update_fields) . " WHERE id = ?");
        $stmt->execute($update_params);

        if (file_exists(__DIR__ . '/getid3/write.php') && file_exists($song['file'])) {
          require_once __DIR__ . '/getid3/write.php';
          $tagwriter = new getid3_writetags;
          $tagwriter->filename = $song['file'];
          $ext = strtolower(pathinfo($song['file'], PATHINFO_EXTENSION));
          if ($ext === 'mp3') {
            $tagwriter->tagformats = ['id3v1', 'id3v2.3'];
          } elseif ($ext === 'flac') {
            $tagwriter->tagformats = ['metaflac']; // Fixed critical missing object pointer
          } elseif ($ext === 'ogg') {
            $tagwriter->tagformats = ['vorbiscomment'];
          } elseif ($ext === 'm4a') {
            $tagwriter->tagformats = ['mp4']; // Added M4A support
          } else {
            $tagwriter->tagformats = ['id3v2.3'];
          }
          $tagwriter->overwrite_tags = true;
          $tagwriter->tag_encoding = 'UTF-8';
          $tagwriter->remove_other_tags = false;
          $tagwriter->tag_data = [
            'title' => [htmlspecialchars_decode($new_title, ENT_QUOTES)],
            'artist' => [htmlspecialchars_decode($new_artist, ENT_QUOTES)],
            'album' => [htmlspecialchars_decode($new_album, ENT_QUOTES)],
            'genre' => [htmlspecialchars_decode($new_genre, ENT_QUOTES)],
            'unsynchronised_lyric' => [htmlspecialchars_decode($new_lyrics, ENT_QUOTES)]
          ];

          if ($jpeg_data) {
            $tagwriter->tag_data['attached_picture'] = [
              [
                'data'          => $jpeg_data,
                'picturetypeid' => 3, // Cover (front)
                'description'   => 'Cover',
                'mime'          => 'image/jpeg'
              ]
            ];
          }
          
          // Force write operation.
          if (!$tagwriter->WriteTags()) {
            // Fallback: If writing the image fails due to an already corrupted ID3 frame inside the physical file, 
            // we wipe the corrupted tags entirely and rewrite the fresh data cleanly.
            $tagwriter->remove_other_tags = true;
            $tagwriter->WriteTags();
          }
          clearstatcache(true, $song['file']);
          $new_mtime = filemtime($song['file']);
          $db->prepare("UPDATE music SET last_modified = ? WHERE id = ?")->execute([$new_mtime, $song_id]);
        }

        send_json(['status' => 'success', 'message' => 'Metadata updated successfully.']);
      } else {
        http_response_code(403);
        send_json(['status' => 'error', 'message' => 'You do not have permission to edit this song.']);
      }
      break;

    case 'get_explore':
      // MASS USE OPTIMIZATION: 5-Minute Micro-Cache for heavy Discovery queries
      $cache_file = sys_get_temp_dir() . '/phpmusic_explore_cache_' . ($user_id ? $user_id : 'guest') . '.json';
      if (file_exists($cache_file)) {
        $cached_content = @file_get_contents($cache_file);
        if (!empty($cached_content) && (time() - filemtime($cache_file)) < 300) {
          $decoded = json_decode($cached_content);
          if ($decoded && isset($decoded->shelves)) {
            header('Content-Type: application/json; charset=utf-8');
            echo $cached_content;
            exit;
          }
        }
      }

      $shelves = [];
      $song_fields = "m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count";
      $album_fields = "m.album, m.artist, m.user_id, MAX(m.id) as id";

      $discovery_songs_stmt = $db->prepare("
        SELECT {$song_fields} FROM music m
        JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 15) r ON m.id = r.id
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :fav_user_id
        " . ($user_id ? "WHERE NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :hist_user_id)" : "") . "
      ");
      $song_params = [':fav_user_id' => $user_id ? $user_id : 0];
      if ($user_id) {
        $song_params[':hist_user_id'] = $user_id;
      }
      $discovery_songs_stmt->execute($song_params);
      $discovery_songs = $discovery_songs_stmt->fetchAll();
      if (count($discovery_songs) > 0) {
        $shelves[] = ['title' => 'Discover Songs', 'type' => 'songs', 'items' => $discovery_songs];
      }
      
      $discovery_stmt = $db->prepare("
        SELECT m.album, m.artist, m.user_id, m.id, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc FROM music m
        WHERE m.album != 'Unknown Album' AND m.album != '' AND m.album IS NOT NULL " . ($user_id ? "AND NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id)" : "") . "
        ORDER BY RANDOM() LIMIT 100
      ");
      $album_params = [];
      if ($user_id) {
        $album_params[':user_id'] = $user_id;
      }
      $discovery_stmt->execute($album_params);
      $disc_rows = $discovery_stmt->fetchAll();
      $discovery_albums = [];
      foreach ($disc_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+|\s*,\s*(?!(?:the|a|an|jr|sr)\b))\s*/i', $row['artist']);
        if (!is_array($parts)) $parts = [$row['artist']];
        foreach ($parts as $part) {
          $p = trim($part);
          if ($p !== '') {
            $key = strtolower($row['album'] . ':::' . $p);
            if (!isset($discovery_albums[$key])) {
              $discovery_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc']];
            } else {
              $discovery_albums[$key]['song_count']++;
              $discovery_albums[$key]['total_plays'] += $row['pc'];
            }
          }
        }
      }
      shuffle($discovery_albums);
      $discovery_albums = array_slice($discovery_albums, 0, 10);
      if (count($discovery_albums) > 0) {
        $shelves[] = ['title' => 'Discover Albums', 'type' => 'albums', 'items' => $discovery_albums];
      }

      $rec_artists_stmt = $db->prepare("
        SELECT m.artist AS name, MAX(m.id) AS id
        FROM music m
        WHERE m.artist != 'Unknown Artist' AND m.artist != '' AND m.artist IS NOT NULL
        " . ($user_id ? "AND NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id)" : "") . "
        GROUP BY m.artist
        ORDER BY RANDOM() LIMIT 50
      ");
      $artist_params = [];
      if ($user_id) {
        $artist_params[':user_id'] = $user_id;
      }
      $rec_artists_stmt->execute($artist_params);
      $rec_artists_rows = $rec_artists_stmt->fetchAll();
      $rec_artists = [];
      $seen_artists = [];
      $stmt_is_user = $db->prepare("SELECT id FROM users WHERE artist = ? COLLATE NOCASE");
      
      foreach ($rec_artists_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['name']);
        if (!is_array($parts)) $parts = [$row['name']];
        foreach ($parts as $part) {
          $p = trim($part);
          $key = strtolower($p);
          if ($p !== '' && !isset($seen_artists[$key])) {
            $seen_artists[$key] = true;
            $stmt_is_user->execute([$p]);
            $uid = $stmt_is_user->fetchColumn();
            $rec_artists[] = [
              'name' => $p,
              'id' => $uid ? $uid : $row['id'],
              'is_user' => (bool)$uid
            ];
            if (count($rec_artists) >= 10) break 2;
          }
        }
      }
      if (count($rec_artists) > 0) {
        $shelves[] = ['title' => 'Discover Artists', 'type' => 'artists', 'items' => $rec_artists];
      }

      if ($user_id) {
        $freq_played_stmt = $db->prepare("
          SELECT {$song_fields}
          FROM play_counts pc JOIN music m ON pc.song_id = m.id
          LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
          WHERE pc.user_id = :user_id
          ORDER BY pc.play_count DESC LIMIT 15
        ");
        $freq_played_stmt->execute([':user_id' => $user_id]);
        $freq_played_songs = $freq_played_stmt->fetchAll();
        if (count($freq_played_songs) > 0) {
          $shelves[] = ['title' => 'Frequently Played', 'type' => 'songs', 'items' => $freq_played_songs];
        }

        $rec_followed_songs_stmt = $db->prepare("
          SELECT {$song_fields} FROM music m
          JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 100) r ON m.id = r.id
          LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
          WHERE m.user_id IN (SELECT following_id FROM follows WHERE follower_id = :user_id)
          LIMIT 15
        ");
        $rec_followed_songs_stmt->execute([':user_id' => $user_id]);
        $rec_followed_songs = $rec_followed_songs_stmt->fetchAll();
        if (count($rec_followed_songs) > 0) {
          $shelves[] = ['title' => 'From Your Artists: New Tracks', 'type' => 'songs', 'items' => $rec_followed_songs];
        }

        $rec_followed_albums_stmt = $db->prepare("
          SELECT m.album, m.artist, m.user_id, m.id, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc FROM music m
          WHERE m.user_id IN (SELECT following_id FROM follows WHERE follower_id = :user_id) AND m.album != 'Unknown Album' AND m.album != '' AND m.album IS NOT NULL
          ORDER BY RANDOM() LIMIT 100
        ");
        $rec_followed_albums_stmt->execute([':user_id' => $user_id]);
        $fol_rows = $rec_followed_albums_stmt->fetchAll();
        $rec_followed_albums = [];
        foreach ($fol_rows as $row) {
          $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['artist']);
          if (!is_array($parts)) $parts = [$row['artist']];
          foreach ($parts as $part) {
            $p = trim($part);
            if ($p !== '') {
              $key = strtolower($row['album'] . ':::' . $p);
              if (!isset($rec_followed_albums[$key])) {
                $rec_followed_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc']];
              } else {
                $rec_followed_albums[$key]['song_count']++;
                $rec_followed_albums[$key]['total_plays'] += $row['pc'];
              }
            }
          }
        }
        shuffle($rec_followed_albums);
        $rec_followed_albums = array_slice($rec_followed_albums, 0, 10);
        if (count($rec_followed_albums) > 0) {
          $shelves[] = ['title' => 'From Your Artists: New Albums', 'type' => 'albums', 'items' => $rec_followed_albums];
        }
      }

      // MASS USE OPTIMIZATION: Save the generated response to the cache file before sending
      $final_json = json_encode(['shelves' => $shelves], JSON_INVALID_UTF8_SUBSTITUTE);
      if ($final_json) {
        @file_put_contents($cache_file, $final_json);
      }
      
      header('Content-Type: application/json; charset=utf-8');
