      // SERVER-SIDE ANTI-CHEAT VALIDATION (V6.2: Multi-Layered, Pattern Analysis, Auto-Ban)
      $hit_deltas = $data['hit_deltas'] ?? [];
      $total_hits = count($hit_deltas);
      $max_combo = intval($data['max_combo'] ?? 0);
      $claimed_score = intval($data['score'] ?? 0);
