        (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count
        FROM music m
        JOIN rhythm_favorites rf ON m.id = rf.song_id
        $where $order_by $limit_clause
      ");
      $stmt->execute($params);
      $songs_result = $stmt->fetchAll();

