        $stmt_lvl->execute($song_ids);
        $lvl_rows = $stmt_lvl->fetchAll();
        $lvl_map = [];
        foreach ($lvl_rows as $row) {
          $lvl_map[$row['song_id']][$row['difficulty']] = (int)$row['level'];
        }
        foreach ($songs_result as &$song) {
          $song['levels'] = $lvl_map[$song['id']] ?? null;
        }
        unset($song);
