    case 'get_recommendations':
      if (!$user_id) { send_json(['shelves' => []]); }
      
      // MASS USE OPTIMIZATION: 5-Minute Micro-Cache for heavy Recommendation queries
      $rec_cache_file = sys_get_temp_dir() . '/phpmusic_rec_cache_' . $user_id . '.json';
      if (file_exists($rec_cache_file)) {
        $cached_content = @file_get_contents($rec_cache_file);
        if (!empty($cached_content) && (time() - filemtime($rec_cache_file)) < 300) {
          $decoded = json_decode($cached_content);
          if ($decoded && isset($decoded->shelves)) {
            header('Content-Type: application/json; charset=utf-8');
            echo $cached_content;
            exit;
          }
        }
      }

      $shelves = [];
      $song_fields = "m.id, m.title, m.artist, m.album, m.genre, m.duration, m.user_id, m.is_private, m.is_collaborative, m.last_modified, CASE WHEN f.song_id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, (SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id) as play_count";
      $album_fields = "m.album, m.artist, m.user_id, MAX(m.id) as id";

      $recent_songs_stmt = $db->prepare("
        SELECT {$song_fields}
        FROM history h JOIN music m ON h.song_id = m.id
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
        WHERE h.user_id = :user_id GROUP BY m.id ORDER BY MAX(h.played_at) DESC LIMIT 10
      ");
      $recent_songs_stmt->execute([':user_id' => $user_id]);
      $recent_songs = $recent_songs_stmt->fetchAll();
      if (count($recent_songs) > 0) {
        $shelves[] = ['title' => 'Recently Played', 'type' => 'songs', 'items' => $recent_songs, 'connected_view' => 'get_history'];
      }

      $top_artists_stmt = $db->prepare("
        SELECT m.artist FROM play_counts pc JOIN music m ON pc.song_id = m.id
        WHERE pc.user_id = ? AND m.artist != 'Unknown Artist'
        GROUP BY m.artist ORDER BY SUM(pc.play_count) DESC LIMIT 1
      ");
      $top_artists_stmt->execute([$user_id]);
      $top_artist = $top_artists_stmt->fetchColumn();

      if ($top_artist) {
        $more_from_artist_stmt = $db->prepare("
          SELECT m.album, m.artist, m.user_id, m.id, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc FROM music m
          JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 200) r ON m.id = r.id
          WHERE match_artist(m.artist, :artist_name) = 1 AND m.album != 'Unknown Album' AND m.album != '' AND m.album IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id)
        ");
        $more_from_artist_stmt->execute([':user_id' => $user_id, ':artist_name' => $top_artist]);
        $artist_rows = $more_from_artist_stmt->fetchAll();
        $artist_albums = [];
        foreach ($artist_rows as $row) {
          $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+|\s*,\s*(?!(?:the|a|an|jr|sr)\b))\s*/i', $row['artist']);
          if (!is_array($parts)) $parts = [$row['artist']];
          foreach ($parts as $part) {
            $p = trim($part);
            if ($p !== '' && strcasecmp($p, $top_artist) === 0) {
              $key = strtolower($row['album'] . ':::' . $p);
              if (!isset($artist_albums[$key])) {
                $artist_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc']];
              } else {
                $artist_albums[$key]['song_count']++;
                $artist_albums[$key]['total_plays'] += $row['pc'];
              }
            }
          }
        }
        $artist_albums = array_slice(array_values($artist_albums), 0, 10);
        if (count($artist_albums) > 0) {
          $shelves[] = ['title' => 'More from ' . $top_artist, 'type' => 'albums', 'items' => $artist_albums, 'connected_view' => 'artist_songs', 'param' => urlencode($top_artist)];
        }
      }

      $top_genres_stmt = $db->prepare("
        SELECT m.genre FROM play_counts pc JOIN music m ON pc.song_id = m.id
        WHERE pc.user_id = ? AND m.genre != '' AND m.genre IS NOT NULL AND m.genre != 'Unknown Genre'
        GROUP BY m.genre ORDER BY SUM(pc.play_count) DESC LIMIT 2
      ");
      $top_genres_stmt->execute([$user_id]);
      $top_genres = $top_genres_stmt->fetchAll(PDO::FETCH_COLUMN);

      if (count($top_genres) > 0) {
        $genre_placeholders = implode(',', array_fill(0, count($top_genres), '?'));
        $genre_mix_stmt = $db->prepare("
          SELECT {$song_fields} FROM music m
          JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 100) r ON m.id = r.id
          LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = ?
          WHERE m.genre IN ({$genre_placeholders}) AND NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = ?)
          LIMIT 15
        ");
        $genre_mix_stmt->execute(array_merge([$user_id], $top_genres, [$user_id]));
        $genre_songs = $genre_mix_stmt->fetchAll();
        if (count($genre_songs) > 0) {
          $shelves[] = ['title' => 'Your Genre Mix', 'type' => 'songs', 'items' => $genre_songs];
        }
      }
      
      $recent_favorites_stmt = $db->prepare("
        SELECT {$song_fields} FROM favorites f JOIN music m ON f.song_id = m.id
        LEFT JOIN favorites f2 ON m.id = f2.song_id AND f2.user_id = :user_id
        WHERE f.user_id = :user_id
        ORDER BY f.sort_order DESC LIMIT 10
      ");
      $recent_favorites_stmt->execute([':user_id' => $user_id]);
      $recent_favorites = $recent_favorites_stmt->fetchAll();
      if (count($recent_favorites) > 0) {
        $shelves[] = ['title' => 'Your Favorites', 'type' => 'songs', 'items' => $recent_favorites, 'connected_view' => 'get_favorites'];
      }

      $recent_playlists_stmt = $db->prepare("
        SELECT p.name, p.public_id, p.is_collaborative, p.is_private, u.artist as creator, p.play_count,
        (SELECT ps.song_id FROM playlist_songs ps WHERE ps.playlist_id = p.id ORDER BY ps.added_at DESC LIMIT 1) as image_id,
        (SELECT COUNT(*) FROM playlist_songs ps WHERE ps.playlist_id = p.id) as song_count
        FROM playlists p JOIN users u ON p.user_id = u.id
        WHERE p.user_id = :user_id
        ORDER BY p.created_at DESC LIMIT 5
      ");
      $recent_playlists_stmt->execute([':user_id' => $user_id]);
      $recent_playlists = $recent_playlists_stmt->fetchAll();
      if (count($recent_playlists) > 0) {
        $shelves[] = ['title' => 'Your Playlists', 'type' => 'playlists', 'items' => $recent_playlists, 'connected_view' => 'get_user_playlists'];
      }

      $discovery_songs_stmt = $db->prepare("
        SELECT {$song_fields} FROM music m
        JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 100) r ON m.id = r.id
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
        WHERE NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id)
        LIMIT 15
      ");
      $discovery_songs_stmt->execute([':user_id' => $user_id]);
      $discovery_songs = $discovery_songs_stmt->fetchAll();
      if (count($discovery_songs) > 0) {
        $shelves[] = ['title' => 'Discover New Songs', 'type' => 'songs', 'items' => $discovery_songs];
      }
      
      $discovery_stmt = $db->prepare("
        SELECT m.album, m.artist, m.user_id, m.id, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc FROM music m
        JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 200) r ON m.id = r.id
        WHERE NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id) AND m.album != 'Unknown Album' AND m.album != '' AND m.album IS NOT NULL
      ");
      $discovery_stmt->execute([':user_id' => $user_id]);
      $disc_rec_rows = $discovery_stmt->fetchAll();
      $discovery_albums = [];
      foreach ($disc_rec_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['artist']);
        if (!is_array($parts)) $parts = [$row['artist']];
        foreach ($parts as $part) {
          $p = trim($part);
          if ($p !== '') {
            $key = strtolower($row['album'] . ':::' . $p);
            if (!isset($discovery_albums[$key])) {
              $discovery_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc']];
            } else {
              $discovery_albums[$key]['song_count']++;
              $discovery_albums[$key]['total_plays'] += $row['pc'];
            }
          }
        }
      }
      $discovery_albums = array_slice(array_values($discovery_albums), 0, 10);
      if (count($discovery_albums) > 0) {
        $shelves[] = ['title' => 'Discover New Albums', 'type' => 'albums', 'items' => $discovery_albums];
      }

      $rec_artists_stmt = $db->prepare("
        SELECT m.artist AS name, MAX(m.id) AS id
        FROM music m
        JOIN (SELECT id FROM music ORDER BY RANDOM() LIMIT 100) r ON m.id = r.id
        WHERE m.artist != 'Unknown Artist' AND m.artist != '' AND m.artist IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM history h WHERE h.song_id = m.id AND h.user_id = :user_id)
        GROUP BY m.artist
        LIMIT 50
      ");
      $rec_artists_stmt->execute([':user_id' => $user_id]);
      $rec_artists_rows = $rec_artists_stmt->fetchAll();
      $rec_artists = [];
      $seen_artists = [];
      $user_artist_map = $db->query("SELECT LOWER(artist), id FROM users WHERE artist IS NOT NULL AND artist != ''")->fetchAll(PDO::FETCH_KEY_PAIR);

      foreach ($rec_artists_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['name']);
        if (!is_array($parts)) $parts = [$row['name']];
        foreach ($parts as $part) {
          $p = trim(preg_replace('/\s*\(id:\d+\)/i', '', $part));
          $key = strtolower($p);
          if ($p !== '' && !isset($seen_artists[$key])) {
            $seen_artists[$key] = true;
            $uid = $user_artist_map[$key] ?? null;
            $rec_artists[] = [
              'name' => $p,
              'id' => $uid ? $uid : $row['id'],
              'is_user' => (bool)$uid
            ];
            if (count($rec_artists) >= 10) break 2;
          }
        }
      }
      if (count($rec_artists) > 0) {
        $shelves[] = ['title' => 'Discover Artists', 'type' => 'artists', 'items' => $rec_artists];
      }

      $freq_played_stmt = $db->prepare("
        SELECT {$song_fields}
        FROM play_counts pc JOIN music m ON pc.song_id = m.id
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
        WHERE pc.user_id = :user_id
        ORDER BY pc.play_count DESC LIMIT 15
      ");
      $freq_played_stmt->execute([':user_id' => $user_id]);
      $freq_played_songs = $freq_played_stmt->fetchAll();
      if (count($freq_played_songs) > 0) {
        $shelves[] = ['title' => 'Frequently Played', 'type' => 'songs', 'items' => $freq_played_songs];
      }

      $mix_seeds_stmt = $db->query("
        SELECT * FROM (
          SELECT DISTINCT artist as seed_name, 'artist' as seed_type FROM music WHERE artist != 'Unknown Artist' AND artist != '' AND artist IS NOT NULL
          UNION
          SELECT DISTINCT genre as seed_name, 'genre' as seed_type FROM music WHERE genre != 'Unknown Genre' AND genre != '' AND genre IS NOT NULL
        ) ORDER BY RANDOM() LIMIT 15
      ");
      $seeds = $mix_seeds_stmt->fetchAll();
      $mixes = [];
      foreach ($seeds as $seed) {
        $song_stmt = $db->prepare("SELECT id FROM music WHERE " . $seed['seed_type'] . " = ? ORDER BY RANDOM() LIMIT 60");
        $song_stmt->execute([$seed['seed_name']]);
        $song_ids = $song_stmt->fetchAll(PDO::FETCH_COLUMN);
        if (count($song_ids) < 50) {
          $needed = 50 - count($song_ids);
          $pad_stmt = $db->query("SELECT id FROM music ORDER BY RANDOM() LIMIT 100");
          $pad_candidates = $pad_stmt->fetchAll(PDO::FETCH_COLUMN);
          foreach ($pad_candidates as $cid) {
            if (!in_array($cid, $song_ids)) {
              $song_ids[] = $cid;
              $needed--;
              if ($needed <= 0) break;
            }
          }
        }
        if (empty($song_ids)) continue;
        $img_stmt = $db->prepare("SELECT id FROM music WHERE " . $seed['seed_type'] . " = ? ORDER BY RANDOM() LIMIT 1");
        $img_stmt->execute([$seed['seed_name']]);
        $img_id = $img_stmt->fetchColumn() ?: $song_ids[0];
        $public_id = bin2hex(random_bytes(8));
        $name = 'Mix - ' . $seed['seed_name'];
          $db->prepare("INSERT INTO mixes (public_id, name, creator, image_id) VALUES (?, ?, ?, ?)")->execute([$public_id, $name, 'PHP-Music', $img_id]);
          $mix_id = $db->lastInsertId();
          $order = 0;
          $insert_ms = $db->prepare("INSERT INTO mix_songs (mix_id, song_id, sort_order) VALUES (?, ?, ?)");
          foreach ($song_ids as $sid) {
            $insert_ms->execute([$mix_id, $sid, $order++]);
          }
          
          $mix_pc_stmt = $db->prepare("SELECT SUM(play_count) FROM play_counts WHERE song_id IN (" . implode(',', $song_ids) . ")");
          $mix_pc_stmt->execute();
          $mix_play_count = $mix_pc_stmt->fetchColumn() ?: 0;
          
          $mixes[] = [
            'public_id' => $public_id,
            'name' => $name,
            'creator' => 'PHP-Music',
            'image_id' => $img_id,
            'song_count' => count($song_ids),
            'play_count' => $mix_play_count
          ];
        }
      if (!empty($mixes)) {
        $shelves[] = ['title' => 'Your Mixes', 'type' => 'mixes', 'items' => $mixes];
      }

      $latest_followed_songs_stmt = $db->prepare("
        SELECT {$song_fields} FROM music m
        LEFT JOIN favorites f ON m.id = f.song_id AND f.user_id = :user_id
        WHERE m.user_id IN (SELECT following_id FROM follows WHERE follower_id = :user_id)
        ORDER BY m.id DESC LIMIT 15
      ");
      $latest_followed_songs_stmt->execute([':user_id' => $user_id]);
      $latest_followed_songs = $latest_followed_songs_stmt->fetchAll();
      if (count($latest_followed_songs) > 0) {
        $shelves[] = ['title' => 'From Your Artists: New Tracks', 'type' => 'songs', 'items' => $latest_followed_songs];
      }

      $latest_followed_albums_stmt = $db->prepare("
        SELECT m.album, m.artist, m.user_id, m.id, COALESCE((SELECT SUM(play_count) FROM play_counts WHERE song_id = m.id), 0) as pc FROM music m
        WHERE m.user_id IN (SELECT following_id FROM follows WHERE follower_id = :user_id) AND m.album != 'Unknown Album' AND m.album != '' AND m.album IS NOT NULL
        ORDER BY id DESC LIMIT 200
      ");
      $latest_followed_albums_stmt->execute([':user_id' => $user_id]);
      $lf_rows = $latest_followed_albums_stmt->fetchAll();
      $latest_followed_albums = [];
      foreach ($lf_rows as $row) {
        $parts = @preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $row['artist']);
        if (!is_array($parts)) $parts = [$row['artist']];
        foreach ($parts as $part) {
          $p = trim($part);
          if ($p !== '') {
            $key = strtolower($row['album'] . ':::' . $p);
            if (!isset($latest_followed_albums[$key])) {
              $latest_followed_albums[$key] = ['album' => $row['album'], 'artist' => $p, 'user_id' => $row['user_id'], 'id' => $row['id'], 'song_count' => 1, 'total_plays' => $row['pc']];
            } else {
              $latest_followed_albums[$key]['song_count']++;
              $latest_followed_albums[$key]['total_plays'] += $row['pc'];
            }
          }
        }
      }
      $latest_followed_albums = array_slice(array_values($latest_followed_albums), 0, 10);
      if (count($latest_followed_albums) > 0) {
        $shelves[] = ['title' => 'From Your Artists: New Albums', 'type' => 'albums', 'items' => $latest_followed_albums];
      }

      // MASS USE OPTIMIZATION: Save to cache
      $final_rec_json = json_encode(['shelves' => $shelves], JSON_INVALID_UTF8_SUBSTITUTE);
      if ($final_rec_json) {
        @file_put_contents($rec_cache_file, $final_rec_json);
      }
      
      header('Content-Type: application/json; charset=utf-8');
      echo $final_rec_json ?: '{"shelves":[]}';
      exit;

    case 'export_tasks':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt = $db->prepare("SELECT title, items, category, starred, created_at, updated_at FROM tasks WHERE user_id = ? ORDER BY created_at ASC");
      $stmt->execute([$user_id]);
      $rows = $stmt->fetchAll();
      if (empty($rows)) { http_response_code(404); exit; }

      $export_data = [
        'name' => 'Tasks',
        'tasks' => $rows
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="tasks.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_tasks':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['tasks']) || !is_array($import_data['tasks'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON payload.']);
      }

      $db->beginTransaction();
      try {
        $stmt_insert = $db->prepare("INSERT INTO tasks (user_id, title, items, category, starred, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)");
        $count = 0;
        foreach ($import_data['tasks'] as $task) {
          $title = isset($task['title']) ? htmlspecialchars($task['title']) : 'Imported Task';
          $items = isset($task['items']) ? $task['items'] : '[]'; 
          $category = isset($task['category']) ? $task['category'] : 'all';
          $starred = isset($task['starred']) ? (int)$task['starred'] : 0;
          $created_at = isset($task['created_at']) ? $task['created_at'] : date('Y-m-d H:i:s');
          $updated_at = isset($task['updated_at']) ? $task['updated_at'] : date('Y-m-d H:i:s');
          
          $stmt_insert->execute([$user_id, $title, $items, $category, $starred, $created_at, $updated_at]);
          $count++;
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Successfully imported {$count} tasks."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500); send_json(['status' => 'error', 'message' => 'Database error during import.']);
      }
      break;

    case 'get_categories':
      if (!$user_id) { send_json([]); }
      $type = $_GET['filter'] ?? $_GET['type'] ?? 'note';
      if ($type === 'task') {
        $stmt = $db->prepare("SELECT id, name, 'task' as category_type, (SELECT COUNT(*) FROM tasks WHERE category = task_categories.id AND user_id = ?) as item_count FROM task_categories WHERE user_id = ? ORDER BY name ASC " . $limit_clause);
      } elseif ($type === 'blog') {
        $stmt = $db->prepare("SELECT id, name, 'blog' as category_type, (SELECT COUNT(*) FROM blogs WHERE category = blog_categories.id AND user_id = ?) as item_count FROM blog_categories WHERE user_id = ? ORDER BY name ASC " . $limit_clause);
      } elseif ($type === 'imageditor') {
        $stmt = $db->prepare("SELECT id, name, 'imageditor' as category_type, (SELECT COUNT(*) FROM imageditor_projects WHERE category = imageditor_categories.id AND user_id = ?) as item_count FROM imageditor_categories WHERE user_id = ? ORDER BY name ASC " . $limit_clause);
      } else {
        $stmt = $db->prepare("SELECT id, name, 'note' as category_type, (SELECT COUNT(*) FROM personal_notes WHERE category = note_categories.id AND user_id = ?) as item_count FROM note_categories WHERE user_id = ? ORDER BY name ASC " . $limit_clause);
      }
      $stmt->execute([$user_id, $user_id]);
      send_json($stmt->fetchAll());
      break;

    case 'export_notes':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt = $db->prepare("SELECT title, content, created_at, updated_at FROM personal_notes WHERE user_id = ? ORDER BY created_at ASC");
      $stmt->execute([$user_id]);
      $rows = $stmt->fetchAll();
      if (empty($rows)) { http_response_code(404); exit; }

      $export_data = [
        'name' => 'Personal Notes',
        'notes' => $rows
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="personal_notes.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_notes':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['notes']) || !is_array($import_data['notes'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON payload.']);
      }

      $db->beginTransaction();
      try {
        $stmt_insert = $db->prepare("INSERT INTO personal_notes (user_id, title, content, created_at, updated_at) VALUES (?, ?, ?, ?, ?)");
        $count = 0;
        foreach ($import_data['notes'] as $note) {
          $title = isset($note['title']) ? htmlspecialchars($note['title']) : 'Imported Note';
          // Raw content from export might already be formatted, but we run it through our standard text wrapper safely
          $content = isset($note['content']) ? format_user_text($note['content']) : ''; 
          $created_at = isset($note['created_at']) ? $note['created_at'] : date('Y-m-d H:i:s');
          $updated_at = isset($note['updated_at']) ? $note['updated_at'] : date('Y-m-d H:i:s');
          
          if ($content !== '') {
            $stmt_insert->execute([$user_id, $title, $content, $created_at, $updated_at]);
            $count++;
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Successfully imported {$count} notes."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500); send_json(['status' => 'error', 'message' => 'Database error during import.']);
      }
      break;

    case 'export_favorites':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt = $db->prepare("
        SELECT m.file, m.title, m.artist, m.album FROM favorites f
        JOIN music m ON f.song_id = m.id 
        WHERE f.user_id = ?
        ORDER BY f.sort_order ASC
      ");
      $stmt->execute([$user_id]);
      $rows = $stmt->fetchAll();
      if (empty($rows)) { http_response_code(404); exit; }

      $song_data = array_map(function($row) {
        return [
          'title' => $row['title'],
          'artist' => $row['artist'],
          'album' => $row['album'],
          'filename' => basename(str_replace('\\', '/', $row['file']))
        ];
      }, $rows);

      $export_data = [
        'name' => 'Favorites',
        'songs' => $song_data
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="favorites.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_favorites':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['songs']) || !is_array($import_data['songs'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON payload.']);
      }

      $db->beginTransaction();
      try {
        $stmt_taa = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE AND album = ? COLLATE NOCASE LIMIT 1");
        $stmt_ta = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE LIMIT 1");
        $stmt_t_artist_match = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND match_artist(artist, ?) = 1 LIMIT 1");
        $stmt_ta_like = $db->prepare("SELECT id FROM music WHERE title LIKE ? COLLATE NOCASE AND artist LIKE ? COLLATE NOCASE LIMIT 1");
        $stmt_file = $db->prepare("SELECT id FROM music WHERE file LIKE ? OR file LIKE ? LIMIT 1");
        $stmt_insert = $db->prepare("INSERT OR IGNORE INTO favorites (user_id, song_id, sort_order) VALUES (?, ?, ?)");
        
        $stmt_order = $db->prepare("SELECT MAX(sort_order) FROM favorites WHERE user_id = ?");
        $stmt_order->execute([$user_id]);
        $order = (int)$stmt_order->fetchColumn();

        $song_count = 0;
        foreach ($import_data['songs'] as $song) {
          $title = is_array($song) ? trim($song['title'] ?? '') : '';
          $artist = is_array($song) ? trim($song['artist'] ?? '') : '';
          $album = is_array($song) ? trim($song['album'] ?? '') : '';
          $filename = basename(str_replace('\\', '/', is_array($song) ? ($song['filename'] ?? '') : $song));
          
          $found_id = null;
          
          if ($title !== '' && $artist !== '') {
            if ($album !== '') {
              $stmt_taa->execute([$title, $artist, $album]);
              $found_id = $stmt_taa->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta->execute([$title, $artist]);
              $found_id = $stmt_ta->fetchColumn();
            }
            if (!$found_id) {
              $stmt_t_artist_match->execute([$title, $artist]);
              $found_id = $stmt_t_artist_match->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta_like->execute(['%' . $title . '%', '%' . $artist . '%']);
              $found_id = $stmt_ta_like->fetchColumn();
            }
          }
          
          if (!$found_id && $filename !== '') {
            $stmt_file->execute(['%/' . $filename, '%\\' . $filename]);
            $found_id = $stmt_file->fetchColumn();
            if (!$found_id) {
              $stmt_file->execute(['%' . $filename, '%' . $filename]);
              $found_id = $stmt_file->fetchColumn();
            }
          }
          
          if ($found_id) {
            $order++;
            $stmt_insert->execute([$user_id, $found_id, $order]);
            if ($stmt_insert->rowCount() > 0) {
              $song_count++;
            }
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Favorites imported with {$song_count} songs."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during import: ' . $e->getMessage()]);
      }
      break;

    case 'clear_favorites':
      if (!$user_id) { http_response_code(403); exit; }
      $db->prepare("DELETE FROM favorites WHERE user_id = ?")->execute([$user_id]);
      send_json(['status' => 'success', 'message' => 'All favorites cleared.']);
      break;

    case 'clear_listen_later':
      if (!$user_id) { http_response_code(403); exit; }
      $db->prepare("DELETE FROM listen_later WHERE user_id = ?")->execute([$user_id]);
      send_json(['status' => 'success', 'message' => 'All Listen Later tracks removed.']);
      break;

    case 'export_listen_later':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt = $db->prepare("
        SELECT m.file, m.title, m.artist, m.album FROM listen_later ll
        JOIN music m ON ll.song_id = m.id 
        WHERE ll.user_id = ?
        ORDER BY ll.sort_order ASC
      ");
      $stmt->execute([$user_id]);
      $rows = $stmt->fetchAll();
      if (empty($rows)) { http_response_code(404); exit; }

      $song_data = array_map(function($row) {
        return [
          'title' => $row['title'],
          'artist' => $row['artist'],
          'album' => $row['album'],
          'filename' => basename(str_replace('\\', '/', $row['file']))
        ];
      }, $rows);

      $export_data = [
        'name' => 'Listen Later',
        'songs' => $song_data
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="listen_later.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_listen_later':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['songs']) || !is_array($import_data['songs'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON payload.']);
      }

      $db->beginTransaction();
      try {
        $stmt_taa = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE AND album = ? COLLATE NOCASE LIMIT 1");
        $stmt_ta = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE LIMIT 1");
        $stmt_t_artist_match = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND match_artist(artist, ?) = 1 LIMIT 1");
        $stmt_ta_like = $db->prepare("SELECT id FROM music WHERE title LIKE ? COLLATE NOCASE AND artist LIKE ? COLLATE NOCASE LIMIT 1");
        $stmt_file = $db->prepare("SELECT id FROM music WHERE file LIKE ? OR file LIKE ? LIMIT 1");
        $stmt_insert = $db->prepare("INSERT OR IGNORE INTO listen_later (user_id, song_id, sort_order) VALUES (?, ?, ?)");
        
        $stmt_order = $db->prepare("SELECT MAX(sort_order) FROM listen_later WHERE user_id = ?");
        $stmt_order->execute([$user_id]);
        $order = (int)$stmt_order->fetchColumn();

        $song_count = 0;
        foreach ($import_data['songs'] as $song) {
          $title = is_array($song) ? trim($song['title'] ?? '') : '';
          $artist = is_array($song) ? trim($song['artist'] ?? '') : '';
          $album = is_array($song) ? trim($song['album'] ?? '') : '';
          $filename = basename(str_replace('\\', '/', is_array($song) ? ($song['filename'] ?? '') : $song));
          
          $found_id = null;
          
          if ($title !== '' && $artist !== '') {
            if ($album !== '') {
              $stmt_taa->execute([$title, $artist, $album]);
              $found_id = $stmt_taa->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta->execute([$title, $artist]);
              $found_id = $stmt_ta->fetchColumn();
            }
            if (!$found_id) {
              $stmt_t_artist_match->execute([$title, $artist]);
              $found_id = $stmt_t_artist_match->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta_like->execute(['%' . $title . '%', '%' . $artist . '%']);
              $found_id = $stmt_ta_like->fetchColumn();
            }
          }
          
          if (!$found_id && $filename !== '') {
            $stmt_file->execute(['%/' . $filename, '%\\' . $filename]);
            $found_id = $stmt_file->fetchColumn();
            if (!$found_id) {
              $stmt_file->execute(['%' . $filename, '%' . $filename]);
              $found_id = $stmt_file->fetchColumn();
            }
          }
          
          if ($found_id) {
            $order++;
            $stmt_insert->execute([$user_id, $found_id, $order]);
            if ($stmt_insert->rowCount() > 0) {
              $song_count++;
            }
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Listen Later imported with {$song_count} songs."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during import: ' . $e->getMessage()]);
      }
      break;

    case 'export_following':
      if (!$user_id) { http_response_code(403); exit; }
      $stmt = $db->prepare("SELECT u.artist FROM follows f JOIN users u ON f.following_id = u.id WHERE f.follower_id = ?");
      $stmt->execute([$user_id]);
      $followings = $stmt->fetchAll(PDO::FETCH_COLUMN);
      if (empty($followings)) { http_response_code(404); exit; }

      $export_data = [
        'name' => 'Following',
        'followings' => $followings
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="following.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_following':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['followings']) || !is_array($import_data['followings'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON payload.']);
      }

      $db->beginTransaction();
      try {
        $stmt_find = $db->prepare("SELECT id FROM users WHERE artist = ? COLLATE NOCASE LIMIT 1");
        $stmt_insert = $db->prepare("INSERT OR IGNORE INTO follows (follower_id, following_id) VALUES (?, ?)");
        
        $count = 0;
        foreach ($import_data['followings'] as $artist) {
          $stmt_find->execute([$artist]);
          $f_id = $stmt_find->fetchColumn();
          if ($f_id && $f_id != $user_id) {
            $stmt_insert->execute([$user_id, $f_id]);
            if ($stmt_insert->rowCount() > 0) {
              $count++;
            }
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Successfully imported {$count} followed artists."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during import.']);
      }
      break;
      
    case 'export_playlist':
      if (!$user_id) { http_response_code(403); exit; }
      $public_id = $_GET['id'] ?? '';
      if (empty($public_id)) { http_response_code(400); exit; }

      $stmt = $db->prepare("
        SELECT p.name, m.file, m.title, m.artist, m.album FROM playlists p 
        JOIN playlist_songs ps ON p.id = ps.playlist_id 
        JOIN music m ON ps.song_id = m.id 
        WHERE p.public_id = ? AND (p.user_id = ? OR {$is_super_admin} = 1) AND (m.is_private = 0 OR m.user_id = ? OR match_artist(m.artist, (SELECT artist FROM users WHERE id = ?)) = 1 OR {$is_super_admin} = 1)
        ORDER BY ps.sort_order ASC
      ");
      $stmt->execute([$public_id, $user_id, $user_id, $user_id]);
      $rows = $stmt->fetchAll();

      if (empty($rows)) { http_response_code(404); exit; }

      $playlist_name = $rows[0]['name'];
      $song_data = array_map(function($row) {
        return [
          'title' => $row['title'],
          'artist' => $row['artist'],
          'album' => $row['album'],
          'filename' => basename(str_replace('\\', '/', $row['file']))
        ];
      }, $rows);

      $export_data = [
        'name' => $playlist_name,
        'songs' => $song_data
      ];
      
      header('Content-Type: application/json');
      header('Content-Disposition: attachment; filename="' . sanitize_for_path($playlist_name) . '.json"');
      echo json_encode($export_data, JSON_PRETTY_PRINT);
      exit;

    case 'import_playlist':
      if (!$user_id) { http_response_code(403); exit; }
      $import_data = json_decode(file_get_contents('php://input'), true);
      if (json_last_error() !== JSON_ERROR_NONE || !isset($import_data['name']) || !isset($import_data['songs']) || !is_array($import_data['songs'])) {
        http_response_code(400); send_json(['status' => 'error', 'message' => 'Invalid or malformed JSON file.']);
      }

      $db->beginTransaction();
      try {
        $public_id = bin2hex(random_bytes(8));
        $stmt_create = $db->prepare("INSERT INTO playlists (user_id, name, public_id) VALUES (?, ?, ?)");
        $stmt_create->execute([$user_id, $import_data['name'], $public_id]);
        $playlist_id = $db->lastInsertId();

        $stmt_taa = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE AND album = ? COLLATE NOCASE LIMIT 1");
        $stmt_ta = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND artist = ? COLLATE NOCASE LIMIT 1");
        $stmt_t_artist_match = $db->prepare("SELECT id FROM music WHERE title = ? COLLATE NOCASE AND match_artist(artist, ?) = 1 LIMIT 1");
        $stmt_ta_like = $db->prepare("SELECT id FROM music WHERE title LIKE ? COLLATE NOCASE AND artist LIKE ? COLLATE NOCASE LIMIT 1");
        $stmt_file = $db->prepare("SELECT id FROM music WHERE file LIKE ? OR file LIKE ? LIMIT 1");
        $stmt_insert = $db->prepare("INSERT OR IGNORE INTO playlist_songs (playlist_id, song_id, sort_order) VALUES (?, ?, ?)");
        
        $song_count = 0;
        $order = 0;
        foreach ($import_data['songs'] as $song) {
          $title = is_array($song) ? trim($song['title'] ?? '') : '';
          $artist = is_array($song) ? trim($song['artist'] ?? '') : '';
          $album = is_array($song) ? trim($song['album'] ?? '') : '';
          $filename = basename(str_replace('\\', '/', is_array($song) ? ($song['filename'] ?? '') : $song));
          
          $found_id = null;
          
          if ($title !== '' && $artist !== '') {
            if ($album !== '') {
              $stmt_taa->execute([$title, $artist, $album]);
              $found_id = $stmt_taa->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta->execute([$title, $artist]);
              $found_id = $stmt_ta->fetchColumn();
            }
            if (!$found_id) {
              $stmt_t_artist_match->execute([$title, $artist]);
              $found_id = $stmt_t_artist_match->fetchColumn();
            }
            if (!$found_id) {
              $stmt_ta_like->execute(['%' . $title . '%', '%' . $artist . '%']);
              $found_id = $stmt_ta_like->fetchColumn();
            }
          }
          
          if (!$found_id && $filename !== '') {
            $stmt_file->execute(['%/' . $filename, '%\\' . $filename]);
            $found_id = $stmt_file->fetchColumn();
            if (!$found_id) {
              $stmt_file->execute(['%' . $filename, '%' . $filename]);
              $found_id = $stmt_file->fetchColumn();
            }
          }
          
          if ($found_id) {
            $stmt_insert->execute([$playlist_id, $found_id, $order]);
            if ($stmt_insert->rowCount() > 0) {
              $order++;
              $song_count++;
            }
          }
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Playlist '{$import_data['name']}' imported with {$song_count} songs."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during import: ' . $e->getMessage()]);
      }
      break;

    case 'copy_playlist':
      if (!$user_id) { http_response_code(403); exit; }
      $public_id = $_POST['public_id'] ?? '';
      if (empty($public_id)) { http_response_code(400); exit; }

      $stmt_source = $db->prepare("SELECT id, name, user_id FROM playlists WHERE public_id = ?");
      $stmt_source->execute([$public_id]);
      $source_playlist = $stmt_source->fetch();

      if (!$source_playlist) { http_response_code(404); send_json(['status' => 'error', 'message' => 'Playlist not found.']); }
      if ($source_playlist['user_id'] == $user_id) { http_response_code(400); send_json(['status' => 'error', 'message' => 'Cannot copy your own playlist.']); }

      $db->beginTransaction();
      try {
        $new_name = "Copy of " . $source_playlist['name'];
        $new_public_id = bin2hex(random_bytes(8));
        $stmt_create = $db->prepare("INSERT INTO playlists (user_id, name, public_id) VALUES (?, ?, ?)");
        $stmt_create->execute([$user_id, $new_name, $new_public_id]);
        $new_playlist_id = $db->lastInsertId();

        $stmt_get_songs = $db->prepare("SELECT song_id, sort_order FROM playlist_songs WHERE playlist_id = ? ORDER BY sort_order ASC");
        $stmt_get_songs->execute([$source_playlist['id']]);
        $songs = $stmt_get_songs->fetchAll();

        $stmt_insert_song = $db->prepare("INSERT INTO playlist_songs (playlist_id, song_id, sort_order) VALUES (?, ?, ?)");
        foreach ($songs as $song) {
          $stmt_insert_song->execute([$new_playlist_id, $song['song_id'], $song['sort_order']]);
        }
        $db->commit();
        send_json(['status' => 'success', 'message' => "Playlist copied successfully."]);
      } catch (Exception $e) {
        $db->rollBack();
        http_response_code(500);
        send_json(['status' => 'error', 'message' => 'Database error during copy: ' . $e->getMessage()]);
      }
      break;
  }
  exit;
}

function perform_force_rescan($db, $mode) {
  $start_time = microtime(true);
  ini_set('memory_limit', '512M');
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  header('Content-Type: text/html; charset=utf-8');
  ob_implicit_flush();

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";

  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Forced Rescan (" . strtoupper($mode) . "). Do not close this window!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Forced Metadata Rescan\n";
  echo "===========================================\n\n";

  if (!class_exists('getID3')) die("FATAL ERROR: getID3 library not found\n");
  
  $getID3 = new getID3;
  $getID3->setOption(['encoding' => 'UTF-8']);
  $getID3->option_md5_data = true;
  $getID3->option_md5_data_source = true;
  $getID3->option_sha1_data = true;
  $getID3->option_tags_html = false;

  $stmt_lib = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1");
  $library_user_id = $stmt_lib->fetchColumn() ?: 1;

  $offset = isset($_GET['offset']) ? (int)$_GET['offset'] : 0;

  $stmt = $db->query("SELECT id, file FROM music ORDER BY id ASC");
  $all_songs = $stmt->fetchAll();
  $total = count($all_songs);

  if ($offset === 0) {
    echo "Found {$total} tracks currently in the database to re-scan.\n\n";
  } else {
    echo "Resuming scan from track " . ($offset + 1) . " of {$total}...\n\n";
  }

  if ($total === 0) die("Database is empty. Please run a Standard Scan first.\n</pre>");

  $songs = array_slice($all_songs, $offset);

  $user_cache = [];
  $stmt_all_users = $db->query("SELECT id, artist FROM users");
  while ($row = $stmt_all_users->fetch()) {
    $user_cache[strtolower($row['artist'])] = $row['id'];
  }
  
  $check_email_stmt = $db->prepare("SELECT id FROM users WHERE email = ?");
  $insert_user_stmt = $db->prepare("INSERT INTO users (email, artist, password_hash, verified, profile_picture, profile_picture_type) VALUES (?, ?, ?, 'no', ?, 'image/svg+xml')");

  $update_artist_stmt = $db->prepare("UPDATE music SET artist = ?, user_id = ? WHERE id = ?");
  $update_song_stmt = $db->prepare("UPDATE music SET title = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, replaygain = ? WHERE id = ?");
  $update_all_stmt = $db->prepare("UPDATE music SET artist = ?, user_id = ?, title = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, replaygain = ? WHERE id = ?");

  $processed = $offset;
  $db->beginTransaction();
  try {
    foreach ($songs as $song) {
      if ((microtime(true) - $start_time) > 40) {
        $db->commit();
        echo "\nApproaching script execution limit. Re-indexing page to resume safely...\n";
        echo "<script>setTimeout(() => window.location.href = '?action=force_rescan&mode=" . urlencode($mode) . "&offset={$processed}', 1000);</script></pre>";
        exit;
      }

      $processed++;
      $percent = floor(($processed / $total) * 100);
      
      $filePath = php_music_require_media_file($song['file']);

      echo sprintf("[%3d%%] [%d/%d] Scanning: %s\n", $percent, $processed, $total, basename($filePath));
      echo "<script>document.getElementById('prog-bar').style.width = '{$percent}%'; document.getElementById('prog-txt').innerText = '{$percent}%'; window.scrollTo(0, document.body.scrollHeight); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$processed}, {$total}, 'Re-scanning " . ucfirst($mode) . "');</script>";

      if ($filePath !== false) {
        $info = $getID3->analyze($filePath);
        getid3_lib::CopyTagsToComments($info);

        $artist_tag = extract_safe_tag($info['comments'] ?? [], 'artist', 'Unknown Artist');
        $file_user_id = $library_user_id;

        if ($mode === 'artists' || $mode === 'all') {
          $main_artist = trim(preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $artist_tag)[0]);
          if ($main_artist !== 'Unknown Artist' && !empty($main_artist)) {
            $artist_lower = strtolower($main_artist);
            if (isset($user_cache[$artist_lower])) {
              $file_user_id = $user_cache[$artist_lower];
            } else {
              echo " -> New artist generated: '{$main_artist}'. Creating account.\n";
              $sanitized_artist_base = sanitize_for_path($main_artist);
              
              // Safely fallback to numbered unknown emails if Transliterator fails on Japanese/Non-English characters
              if ($sanitized_artist_base === 'unknown' || empty($sanitized_artist_base)) {
                $sanitized_artist_base = 'unknown';
                $email = 'unknown1@mail.com';
              } else {
                $email = $sanitized_artist_base . '@mail.com';
              }
              
              $password = $sanitized_artist_base;
              $hash = password_hash($password, PASSWORD_DEFAULT);
              
              $counter = 1;
              while (true) {
                $check_email_stmt->execute([$email]);
                if (!$check_email_stmt->fetch()) break;
                $counter++;
                $email = $sanitized_artist_base . $counter . '@mail.com';
              }
              
              $initial = mb_strtoupper(mb_substr($main_artist, 0, 1, 'UTF-8'));
              $colors = ['#f44336', '#e91e63', '#9c27b0', '#673ab7', '#3f51b5', '#2196f3', '#03a9f4', '#00bcd4', '#009688', '#4caf50', '#8bc34a', '#cddc39', '#ffeb3b', '#ffc107', '#ff9800', '#ff5722', '#795548'];
              $bg_color = $colors[array_rand($colors)];
              $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="'.$bg_color.'"/><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="100" font-weight="bold" fill="#ffffff">' . htmlspecialchars($initial) . '</text></svg>';
              
              $insert_user_stmt->execute([$email, $main_artist, $hash, $svg]);
              $file_user_id = $db->lastInsertId();
              $user_cache[$artist_lower] = $file_user_id; 
            }
          }
        }

        if ($mode === 'songs' || $mode === 'all') {
          $title = extract_safe_tag($info['comments'] ?? [], 'title', pathinfo($filePath, PATHINFO_FILENAME));
          $album = extract_safe_tag($info['comments'] ?? [], 'album', 'Unknown Album');
          $genre = extract_safe_tag($info['comments'] ?? [], 'genre', 'Unknown Genre');
          $year = (int)($info['comments']['year'][0] ?? 0);
          $duration = (int)($info['playtime_seconds'] ?? 0);
          $bitrate = (int)($info['audio']['bitrate'] ?? 0);
          
          $replaygain = 0;
          if (!empty($info['tags']['id3v2']['TXXX'])) {
            foreach($info['tags']['id3v2']['TXXX'] as $txxx) {
              if (strtoupper($txxx['description'] ?? '') === 'REPLAYGAIN_TRACK_GAIN') {
                $replaygain = (float)str_replace(' dB', '', $txxx['data']);
              }
            }
          } elseif (!empty($info['comments']['replaygain_track_gain'][0])) {
            $replaygain = (float)str_replace(' dB', '', $info['comments']['replaygain_track_gain'][0]);
          }
        }

        if ($mode === 'artists') {
          $update_artist_stmt->execute([$artist_tag, $file_user_id, $song['id']]);
        } elseif ($mode === 'songs') {
          $update_song_stmt->execute([$title, $album, $genre, $year, $duration, $bitrate, $replaygain, $song['id']]);
        } else {
          $update_all_stmt->execute([$artist_tag, $file_user_id, $title, $album, $genre, $year, $duration, $bitrate, $replaygain, $song['id']]);
        }

      } else {
        echo " -> File warning: Track path could not be found physically on disk.\n";
      }

      if ($processed % 100 === 0) {
        $db->commit();
        gc_collect_cycles();
        $db->beginTransaction();
      }
    }
    $db->commit();
  } catch (Exception $e) {
    if ($db->inTransaction()) $db->rollBack();
    die("\nFATAL TRANSACTION ERROR: " . $e->getMessage() . "\n</pre>");
  }

  echo "\n=======================\n";
  echo "Forced Rescan ($mode) complete! Processed items: $processed\n</pre>";
  echo "<script>if (window.parent && window.parent.finishScan) window.parent.finishScan('full-scan-modal');</script>";
}

function perform_full_scan($db) {
  global $auto_scan;
  // OPTIMIZATION 1: Release session lock instantly so the iframe and main app don't hang!
  session_write_close();
  
  $start_time = microtime(true);
  ini_set('memory_limit', '1024M'); // Boost memory for large libraries
  set_time_limit(0); // Prevent PHP timeout limits
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  // Remove any conflicting gzip headers before we output
  header_remove('Content-Encoding');
  header('Content-Type: text/html; charset=utf-8');
  header('Cache-Control: no-cache');
  
  // OPTIMIZATION 2: Clean output buffers instead of flushing to prevent corrupted GZIP rendering (blank white page)
  while (ob_get_level() > 0) {
    @ob_end_clean();
  }
  ob_implicit_flush(true);

  $step = isset($_GET['step']) ? (int)$_GET['step'] : 1;
  
  // OPTIMIZATION 3: Safe local temp file for queue state (Fixes Windows/XAMPP sys_get_temp_dir issues)
  $tmp_dir = DATA_ROOT . '/.tmp_db';
  if (!is_dir($tmp_dir)) @mkdir($tmp_dir, 0755, true);
  $queue_file = $tmp_dir . '/phpmusic_scan_queue.json';

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";
  
  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Please wait and don't close this modal, the process can take very long!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Full Scan (Optimized Queue System)\n";
  echo "========================================================\n\n";

  echo "<script>
    const setProgress = (pct) => {
      document.getElementById('prog-bar').style.width = pct + '%';
      document.getElementById('prog-txt').innerText = pct + '%';
      window.scrollTo(0, document.body.scrollHeight);
    };
  </script>";

  if (!class_exists('getID3')) {
    die("FATAL ERROR: getID3 library not found in " . __DIR__ . "/getid3/\n");
  }

  // Initialize DB schemas safely
  init_db($db);

  if ($step === 1) {
    echo "Step 1: Database ready.\n\n";
    echo "Step 2: Verifying Super Admin user...\n";
    $stmt = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1");
    $library_user_id = $stmt->fetchColumn() ?: 1;
    echo "'Music Library' user ID: {$library_user_id}\n\n";

    echo "Step 3: Discovering music files on disk...\n";
    $files_on_disk = [];
    $music_folders = [MEDIA_ROOT];
    $file_count = 0;

    foreach ($music_folders as $folder) {
      if (!is_dir($folder)) continue;
      echo "Scanning directory: " . str_replace('\\', '/', $folder) . "\n";
      
      // OPTIMIZATION 4: Windows Localhost Fix: Force UNIX paths via Iterator to normalize slashes securely
      $dir = new RecursiveDirectoryIterator($folder, FilesystemIterator::SKIP_DOTS | FilesystemIterator::UNIX_PATHS);
      $filter = new RecursiveCallbackFilterIterator($dir, function ($current, $key, $iterator) {
        if ($current->isDir()) {
          // Exclude application caches and NAS service folders. ASUSTOR's
          // #Recycle directory is commonly visible but unreadable to Apache.
          $exclude = ['.git', 'getid3', '.drive_trash_bin', '.drive_thumbnails', '.file_version', '.tmp_db', 'covers', '#recycle', '@eadir'];
          if (in_array(strtolower($current->getFilename()), $exclude, true)) return false;

          // A single protected directory must not abort discovery of the rest
          // of a valid media library.
          if (!is_readable($current->getPathname())) {
            echo " -> Skipping unreadable directory: " . str_replace('\\\\', '/', $current->getPathname()) . "\\n";
            return false;
          }
        }
        return true;
      });
      
      $iterator = new RecursiveIteratorIterator(
        $filter,
        RecursiveIteratorIterator::LEAVES_ONLY,
        RecursiveIteratorIterator::CATCH_GET_CHILD
      );
      foreach ($iterator as $file) {
        if ($file->isDir()) continue;
        
        // Absolute brute-force replacement to guarantee no backslashes on Windows environments
        $filePath = str_replace('\\', '/', $file->getPathname());
        
        if (php_music_supported_media_file($filePath) && php_music_path_within($filePath, MEDIA_ROOT)) {
          $storedPath = php_music_store_media_path($filePath);
          if ($storedPath === false) continue;
          $files_on_disk[$storedPath] = $file->getMTime();
          $file_count++;
          
          // Dynamic progress feedback for massive libraries so the browser doesn't freeze
          if ($file_count % 500 === 0) {
            echo " -> Discovered {$file_count} valid audio files...\n";
            @ob_flush(); flush();
          }
        }
      }
    }
    
    echo "Found a total of {$file_count} music files on disk.\n\n";

    echo "Step 4: Migrating legacy absolute media paths to portable paths...\n";
    // Convert all existing DB slashes to forward slashes to normalize
    $max_retries = 15;
    for ($attempt = 0; $attempt < $max_retries; $attempt++) {
      try {
        $db->exec("UPDATE music SET file = REPLACE(file, '\\', '/')"); 
        break;
      } catch (Exception $e) {
        if (strpos(strtolower($e->getMessage()), 'locked') !== false || strpos(strtolower($e->getMessage()), 'busy') !== false) {
          usleep(rand(20000, 50000));
        } else {
          break; // Unrelated error
        }
      }
    }
    
    $legacyRows = $db->query("SELECT id, file FROM music WHERE file NOT LIKE 'media://%'")->fetchAll();
    $migratePath = $db->prepare("UPDATE music SET file = ? WHERE id = ?");
    $migrated = 0;
    foreach ($legacyRows as $legacyRow) {
      $portable = php_music_store_media_path($legacyRow['file']);
      if ($portable !== false) {
        $migratePath->execute([$portable, $legacyRow['id']]);
        $migrated++;
      }
    }
    echo " -> Migrated {$migrated} legacy path(s). Unresolved legacy records will be replaced by the scan.\n\n";

    echo "Step 5: Fetching existing music records from database...\n";
    $db_files = $db->query("SELECT file, last_modified FROM music")->fetchAll(PDO::FETCH_KEY_PAIR);
    echo "Found " . count($db_files) . " records in the database.\n\n";

    echo "Step 6: Building differential processing queue...\n";
    // Calculate the diffs
    $files_to_add = array_diff_key($files_on_disk, $db_files);
    $files_to_delete = array_diff_key($db_files, $files_on_disk);
    $files_to_update = [];

    foreach (array_intersect_key($files_on_disk, $db_files) as $filePath => $mtime) {
      if ($mtime != $db_files[$filePath]) {
        $files_to_update[$filePath] = $mtime;
      }
    }

    $unchanged_count = count(array_intersect_key($files_on_disk, $db_files)) - count($files_to_update);
    echo " - Existing (Unchanged): " . $unchanged_count . "\n";
    echo " - To add: " . count($files_to_add) . "\n";
    echo " - To update: " . count($files_to_update) . "\n";
    echo " - To delete: " . count($files_to_delete) . "\n\n";

    // Construct the sequential task queue
    $process_queue = array_merge(
      array_map(function($f, $m) { return ['type' => 'process', 'file' => $f, 'mtime' => $m]; }, array_keys($files_to_add), array_values($files_to_add)),
      array_map(function($f, $m) { return ['type' => 'process', 'file' => $f, 'mtime' => $m]; }, array_keys($files_to_update), array_values($files_to_update)),
      array_map(function($f) { return ['type' => 'delete', 'file' => $f]; }, array_keys($files_to_delete))
    );

    $total_tasks = count($process_queue);

    if ($total_tasks === 0) {
      if (file_exists($queue_file)) @unlink($queue_file);
      echo "<script>setProgress(100); if (window.parent && window.parent.finishScan) window.parent.finishScan('full-scan-modal');</script>";
      die("Scan complete. No changes detected.\n</pre>");
    }

    file_put_contents($queue_file, json_encode(['total' => $total_tasks, 'completed' => 0, 'tasks' => $process_queue]));
    
    echo "Queue built successfully! Redirecting to processing engine...\n";
    echo "<script>setTimeout(() => window.location.href = '?action=full_scan&step=2', 1000);</script></pre>";
    exit;
  }

  if ($step === 2) {
    if (!file_exists($queue_file)) {
      die("Queue file lost or scan completed. You can close this window.\n</pre>");
    }

    $queue_data = json_decode(file_get_contents($queue_file), true);
    $tasks = $queue_data['tasks'];
    $completed = $queue_data['completed'];
    $total = $queue_data['total'];

    if (empty($tasks)) {
      @unlink($queue_file);
      echo "<script>setProgress(100);</script>";
      die("\n=======================\nScan completed successfully!\nTotal processed: {$total}\n</pre>");
    }

    // OPTIMIZATION 5: Batch processing (25 items at a time) to prevent PHP max_execution_time limits!
    $batch_size = 25;
    $current_batch = array_slice($tasks, 0, $batch_size);
    $remaining_tasks = array_slice($tasks, $batch_size);

    $getID3 = new getID3;
    $getID3->setOption(['encoding' => 'UTF-8']);
    $getID3->option_md5_data = true;
    $getID3->option_md5_data_source = true;
    $getID3->option_sha1_data = true;
    $getID3->option_tags_html = false;

    $library_user_id = $db->query("SELECT id FROM users WHERE status = 'super_admin' LIMIT 1")->fetchColumn() ?: 1;

    $insert_stmt = $db->prepare("INSERT INTO music (user_id, file, title, artist, album, genre, year, duration, bitrate, image, last_modified) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
    $update_img = $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, image = ?, last_modified = ? WHERE file = ?");
    $update_no_img = $db->prepare("UPDATE music SET title = ?, artist = ?, album = ?, genre = ?, year = ?, duration = ?, bitrate = ?, last_modified = ? WHERE file = ?");
    $delete_stmt = $db->prepare("DELETE FROM music WHERE file = ?");
    $check_file = $db->prepare("SELECT id FROM music WHERE file = ?");
    
    $user_cache = [];
    $stmt_all_users = $db->query("SELECT id, artist FROM users");
    while ($row = $stmt_all_users->fetch()) {
      $user_cache[strtolower($row['artist'])] = $row['id'];
    }
    
    $check_email = $db->prepare("SELECT id FROM users WHERE email = ?");
    $insert_user = $db->prepare("INSERT INTO users (email, artist, password_hash, verified, profile_picture, profile_picture_type) VALUES (?, ?, ?, 'no', ?, 'image/svg+xml')");

    $db->beginTransaction();

    foreach ($current_batch as $task) {
      $completed++;
      $percent = floor(($completed / $total) * 100);

      if ($task['type'] === 'delete') {
        echo sprintf("[%3d%%] [%d/%d] Deleting: %s\n", $percent, $completed, $total, basename($task['file']));
        $delete_stmt->execute([$task['file']]);
      } else {
        echo sprintf("[%3d%%] [%d/%d] Processing: %s\n", $percent, $completed, $total, basename($task['file']));
      echo "<script>if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$completed}, {$total}, 'Scanning Library');</script>";
        
        $storedFilePath = $task['file'];
        $filePath = php_music_require_media_file($storedFilePath);
        $mtime = $task['mtime'];

        if ($filePath === false) {
          echo " -> Rejected path outside MEDIA_ROOT or unsupported media type.\n";
          continue;
        }

        try {
          $info = $getID3->analyze($filePath);
          getid3_lib::CopyTagsToComments($info);
          
          $title = extract_safe_tag($info['comments'] ?? [], 'title', pathinfo($filePath, PATHINFO_FILENAME));
          $artist_tag = extract_safe_tag($info['comments'] ?? [], 'artist', 'Unknown Artist');
          $album = extract_safe_tag($info['comments'] ?? [], 'album', 'Unknown Album');
          $genre = extract_safe_tag($info['comments'] ?? [], 'genre', 'Unknown Genre');
          $year = (int)($info['comments']['year'][0] ?? 0);
          $duration = (int)($info['playtime_seconds'] ?? 0);
          $bitrate = (int)($info['audio']['bitrate'] ?? 0);
          
          $raw_image_data = $info['comments']['picture'][0]['data'] ?? null;
          if (!$raw_image_data) {
            $dir = pathinfo($filePath, PATHINFO_DIRNAME);
            $filename = pathinfo($filePath, PATHINFO_FILENAME);
            $possible_covers = [$filename . '.jpg', $filename . '.png', 'cover.jpg', 'cover.png', 'folder.jpg', 'folder.png', 'artwork.jpg'];
            foreach ($possible_covers as $cfile) {
              $cpath = $dir . '/' . $cfile;
              if (is_file($cpath) && php_music_path_within($cpath, MEDIA_ROOT)) {
                $raw_image_data = @file_get_contents($cpath);
                if ($raw_image_data) break;
              }
            }
          }
          $webp_image_data = process_image_to_webp($raw_image_data);
          
          $check_file->execute([$storedFilePath]);
          $is_update = $check_file->fetchColumn();

          if ($is_update) {
            if ($webp_image_data !== null) {
              $update_img->execute([$title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $webp_image_data, $mtime, $storedFilePath]);
            } else {
              $update_no_img->execute([$title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $mtime, $storedFilePath]);
            }
          } else {
            $file_user_id = $library_user_id;
            $main_artist = trim(preg_split('/\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i', $artist_tag)[0]);

            if ($main_artist !== 'Unknown Artist' && !empty($main_artist)) {
              $artist_lower = strtolower($main_artist);
              if (isset($user_cache[$artist_lower])) {
                $file_user_id = $user_cache[$artist_lower];
              } else {
                echo " -> New artist: '{$main_artist}'. Creating account.\n";
                $sanitized_artist_base = sanitize_for_path($main_artist);
                $hash = password_hash($sanitized_artist_base, PASSWORD_DEFAULT);
                
                $email = $sanitized_artist_base . '@mail.com';
                if ($sanitized_artist_base === 'unknown') {
                  $email = 'unknown1@mail.com';
                }
                $counter = 1;
                while (true) {
                  $check_email->execute([$email]);
                  if (!$check_email->fetch()) break;
                  $counter++;
                  $email = $sanitized_artist_base . $counter . '@mail.com';
                }
                
                $initial = mb_strtoupper(mb_substr($main_artist, 0, 1, 'UTF-8'));
                $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#ffffff"/><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="100" font-weight="bold" fill="#121212">' . htmlspecialchars($initial) . '</text></svg>';
                
                $insert_user->execute([$email, $main_artist, $hash, $svg]);
                $file_user_id = $db->lastInsertId();
                $user_cache[$artist_lower] = $file_user_id; 
              }
            }
            $insert_stmt->execute([$file_user_id, $storedFilePath, $title, $artist_tag, $album, $genre, $year, $duration, $bitrate, $webp_image_data, $mtime]);
          }
        } catch (Exception $e) {
          echo " -> Error processing " . basename($filePath) . ": " . $e->getMessage() . "\n";
        }
      }

      echo "<script>setProgress({$percent}); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$completed}, {$total});</script>";
      @ob_flush(); flush();
    }

    $db->commit();

    $queue_data['tasks'] = $remaining_tasks;
    $queue_data['completed'] = $completed;
    file_put_contents($queue_file, json_encode($queue_data));

    if (empty($remaining_tasks)) {
      @unlink($queue_file);
      echo "<script>setProgress(100); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$total}, {$total}, 'Scanning Library');</script>";
      echo "\n=======================\nScan completed successfully!\nTotal processed: {$total}\n</pre>";
      echo "<script>
        if (window.parent) {
          if (window.parent.finishScan) window.parent.finishScan('full-scan-modal');
        }
      </script>";
    } else {
      echo "\nBatch complete. Loading next {$batch_size}...\n";
      echo "<script>setTimeout(() => window.location.href = '?action=full_scan&step=2', 100);</script></pre>";
    }
  }
}

function perform_cover_scan($db) {
  $start_time = microtime(true);
  ini_set('memory_limit', '512M');
  error_reporting(E_ALL & ~E_DEPRECATED);
  ini_set('display_errors', 1);

  header('Content-Type: text/html; charset=utf-8');
  ob_implicit_flush();

  echo "<style>
    body { color: #e0e0e0; background-color: #030303; font-family: Consolas, 'Courier New', monospace; padding: 10px; margin: 0; }
    pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; margin-top: 75px; }
    #header-wrap { position: fixed; top: 0; left: 0; right: 0; background: #121212; border-bottom: 1px solid #333; z-index: 10; }
    #prog-wrap { padding: 12px 15px 5px 15px; display: flex; align-items: center; }
    #prog-track { flex-grow: 1; background: #000; height: 12px; border-radius: 6px; overflow: hidden; margin-right: 15px; }
    #prog-bar { width: 0%; height: 100%; background: #ff0000; transition: width 0.1s; }
    #prog-txt { font-weight: bold; min-width: 45px; text-align: right; font-size: 14px;}
    #warning-txt { padding: 0 15px 12px 15px; color: #ffc107; font-size: 12px; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 0.5px; }
  </style>";

  echo "<div id='header-wrap'>
          <div id='prog-wrap'><div id='prog-track'><div id='prog-bar'></div></div><div id='prog-txt'>0%</div></div>
          <div id='warning-txt'>⚠️ Re-scanning metadata cover arts. Do not close this window!</div>
        </div>";
  echo "<pre>";
  echo "PHP Music Library - Cover Rescan Process\n";
  echo "=========================================\n\n";

  if (!class_exists('getID3')) {
    die("FATAL ERROR: getID3 library not found in " . __DIR__ . "/getid3/\n");
  }

  $getID3 = new getID3;
  $getID3->setOption(['encoding' => 'UTF-8']);
  $getID3->option_tags_html = false;

  $stmt = $db->query("SELECT id, file, title FROM music WHERE image IS NULL");
  $songs_to_process = $stmt->fetchAll();
  $total = count($songs_to_process);

  echo "Found {$total} tracks currently missing cover images in the database.\n\n";

  if ($total === 0) {
    die("All covers are already processed! No action required.\n</pre>");
  }

  $update_stmt = $db->prepare("UPDATE music SET image = ? WHERE id = ?");
  $processed = 0;

  $db->beginTransaction();
  try {
    foreach ($songs_to_process as $song) {
      if ((microtime(true) - $start_time) > 40) {
        $db->commit();
        echo "\nApproaching script execution limit. Re-indexing page to resume safely...\n";
        echo "<script>setTimeout(() => window.location.reload(), 1000);</script></pre>";
        exit;
      }

      $processed++;
      $percent = floor(($processed / $total) * 100);
      echo sprintf("[%3d%%] [%d/%d] Scanning: %s\n", $percent, $processed, $total, basename($song['file']));
      echo "<script>document.getElementById('prog-bar').style.width = '{$percent}%'; document.getElementById('prog-txt').innerText = '{$percent}%'; window.scrollTo(0, document.body.scrollHeight); if (window.parent && window.parent.updateScanPill) window.parent.updateScanPill({$processed}, {$total}, 'Scanning Covers');</script>";

      $filePath = php_music_require_media_file($song['file']);

      if ($filePath !== false) {
        $info = $getID3->analyze($filePath);
        getid3_lib::CopyTagsToComments($info);
        $raw_image_data = $info['comments']['picture'][0]['data'] ?? null;

        if (!$raw_image_data) {
          $file_info = pathinfo($filePath);
          $dir = $file_info['dirname'];
          $filename = $file_info['filename'];
          $neighbors = [$filename . '.jpg', $filename . '.png', 'cover.jpg', 'cover.png', 'folder.jpg', 'folder.png', 'artwork.jpg'];
          foreach ($neighbors as $nfile) {
            $npath = $dir . '/' . $nfile;
            if (is_file($npath) && php_music_path_within($npath, MEDIA_ROOT)) {
              $raw_image_data = @file_get_contents($npath);
              if ($raw_image_data) break;
            }
          }
        }

        if ($raw_image_data) {
          $webp_data = process_image_to_webp($raw_image_data);
          if ($webp_data) {
            $update_stmt->execute([$webp_data, $song['id']]);
            echo " -> Successfully recovered and converted cover art.\n";
          }
        }
      } else {
        echo " -> File warning: Track path could not be found physically on disk.\n";
      }

      if ($processed % 100 === 0) {
        $db->commit();
        gc_collect_cycles();
        $db->beginTransaction();
      }
    }
    $db->commit();
  } catch (Exception $e) {
    if ($db->inTransaction()) $db->rollBack();
    die("\nFATAL TRANSACTION ERROR: " . $e->getMessage() . "\n</pre>");
  }

  echo "\n=======================\n";
  echo "Cover rescan process complete! Recovered items: $processed\n</pre>";
  echo "<script>if (window.parent && window.parent.finishScan) window.parent.finishScan('cover-scan-modal');</script>";
}
